window.CATALOG = {"categories": [{"id": "physics", "name": {"zh": "物理", "en": "Physics"}, "lessons": [{"id": "force-motion", "name": {"zh": "力與運動", "en": "Force & Motion"}, "versions": {"en": "force-motion-en"}}, {"id": "circuits", "name": {"zh": "電路與歐姆定律", "en": "Circuits & Ohm’s Law"}, "versions": {"zh": "circuits-zh", "en": "circuits-en"}}, {"id": "waves", "name": {"zh": "波動、聲音與光", "en": "Waves, Sound & Light"}, "versions": {"zh": "waves-zh", "en": "waves-en"}}]}, {"id": "chemistry", "name": {"zh": "化學", "en": "Chemistry"}, "lessons": [{"id": "chem-reactions", "name": {"zh": "化學反應與質量守恆", "en": "Chemical Reactions & Conservation of Mass"}, "versions": {"en": "chem-reactions-en"}}, {"id": "chem-acids", "name": {"zh": "酸、鹼、鹽", "en": "Acids, Bases & Salts"}, "versions": {"en": "chem-acids-en"}}, {"id": "chem-redox", "name": {"zh": "氧化與還原", "en": "Oxidation & Reduction"}, "versions": {"en": "chem-redox-en"}}]}, {"id": "biology", "name": {"zh": "生物", "en": "Biology"}, "lessons": [{"id": "bio-osmosis", "name": {"zh": "細胞：滲透作用", "en": "Cells: Osmosis"}, "versions": {"en": "bio-osmosis-en"}}, {"id": "bio-genetics", "name": {"zh": "遺傳：顯性與隱性", "en": "Genetics: Dominant & Recessive"}, "versions": {"en": "bio-genetics-en"}}, {"id": "bio-ecology", "name": {"zh": "生態：食物網與能量金字塔", "en": "Ecology: Food Webs & Energy Pyramids"}, "versions": {"en": "bio-ecology-en"}}]}]};
window.DECKS = {"force-motion-en": {"title": "Force & Motion", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS FROM ZERO · LESSON 1</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Force &amp;<br>Motion</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Why do things move, and why do they stop?<br>Three rules explain it all.</p>\n</div>\n<svg aria-label=\"A hand pushes a cart to the right; an orange arrow shows the force and a blue arrow shows the cart speeding up\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<line x1=\"20\" y1=\"400\" x2=\"700\" y2=\"400\" stroke=\"#6D7F7B\" stroke-width=\"8\"/>\n<rect x=\"240\" y=\"230\" width=\"260\" height=\"130\" rx=\"16\" fill=\"#F3F5F2\"/>\n<rect x=\"270\" y=\"200\" width=\"200\" height=\"40\" rx=\"10\" fill=\"#BFCDC9\"/>\n<circle cx=\"300\" cy=\"380\" r=\"22\" fill=\"#18262B\" stroke=\"#F3F5F2\" stroke-width=\"8\"/>\n<circle cx=\"440\" cy=\"380\" r=\"22\" fill=\"#18262B\" stroke=\"#F3F5F2\" stroke-width=\"8\"/>\n<line x1=\"40\" y1=\"295\" x2=\"190\" y2=\"295\" stroke=\"#E58A55\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<polygon points=\"186,265 236,295 186,325\" fill=\"#E58A55\"/>\n<line x1=\"530\" y1=\"130\" x2=\"650\" y2=\"130\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"646,106 690,130 646,154\" fill=\"#7FB0F2\"/>\n<line x1=\"530\" y1=\"170\" x2=\"610\" y2=\"170\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n<line x1=\"530\" y1=\"90\" x2=\"590\" y2=\"90\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied physics. We start from everyday experiences, like being thrown forward when a bus brakes, and build up to Newton’s three laws."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why do you lurch forward when the bus brakes?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">The bus stops</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The brakes push on the bus and slow it down. <b style=\"color:#18262B\">Nothing pushes you backward.</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Your body keeps going</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Your body was moving at the bus’s speed, and it <b style=\"color:#18262B\">wants to keep moving</b>.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">No one shoved you. That feeling has a name, and it’s the first of three rules we’ll learn today.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 2</p>\n\n</section>", "note": "Ask students first: what pushed you forward? Most will say “the bus” or “the brakes.” The surprise is that nothing pushed you forward at all. Your body simply kept moving. That is inertia, Newton’s first law."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M6 4l14 8-14 8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain inertia</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say why moving things keep moving and still things stay still.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use F = ma</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Work out acceleration from a force and a mass.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Spot force pairs</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Find the action–reaction pair in a push or a pull.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 3</p>\n\n</section>", "note": "The three goals match Newton’s three laws. After the laws, we read a velocity–time graph, bust a common myth and finish with a quick quiz."}, {"id": "basics", "html": "<section id=\"basics\" data-section=\"Before you start: speed, acceleration and force\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Speed</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">How far you go each second. <b style=\"color:#18262B\">10 m/s</b> means 10 meters every second.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Acceleration</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">How much speed changes each second. 0 → 10 → 20 m/s is <b style=\"color:#18262B\">10 m/s²</b>.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Force</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A push or a pull, measured in <b style=\"color:#18262B\">newtons (N)</b>. Holding an apple takes about 1 N.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Net force</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">All the forces added up. 5 N left + 5 N right = <b style=\"color:#18262B\">0 N</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 4</p>\n\n</section>", "note": "Blue cards describe motion; orange cards describe what causes it. “Net force” is the key idea for the laws that follow: if the pushes cancel out, the net force is zero."}, {"id": "law1", "html": "<section id=\"law1\" data-section=\"Newton’s three laws of motion\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">NEWTON’S FIRST LAW</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Inertia: things keep doing what they’re doing</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A card is pulled quickly out from under a cup on a table; the cup stays where it was\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"40\" y=\"250\" width=\"440\" height=\"20\" fill=\"#18262B\"/>\n<rect x=\"70\" y=\"270\" width=\"18\" height=\"90\" fill=\"#18262B\"/>\n<rect x=\"432\" y=\"270\" width=\"18\" height=\"90\" fill=\"#18262B\"/>\n<rect x=\"150\" y=\"238\" width=\"420\" height=\"12\" fill=\"#9AAAA6\"/>\n<polygon points=\"200,120 290,120 280,238 210,238\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"490\" y1=\"200\" x2=\"580\" y2=\"200\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"576,178 616,200 576,222\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Pull the card out fast: the cup stays put.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Objects are “lazy.” A still object stays still. A moving object keeps going at the <b>same speed in a straight line</b>.</p>\n<p style=\"font-size:40px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">No net force → no change in motion</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\"><b style=\"color:#B4521F\">Myth:</b> a moving object needs a constant push.<br><b style=\"color:#2463B8\">Fact:</b> a hockey puck glides on its own. It only stops because friction slows it down.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 5</p>\n\n</section>", "note": "Do the card-and-cup trick live if you can. Back to the bus: your body kept moving because no force stopped it, so you lurched forward. On ice with almost no friction, a puck slides a very long way."}, {"id": "law2", "html": "<section id=\"law2\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">NEWTON’S SECOND LAW</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">F</p>\n<p style=\"font-size:32px;color:#BFCDC9\">force (N)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">m</p>\n<p style=\"font-size:32px;color:#BFCDC9\">mass (kg)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">a</p>\n<p style=\"font-size:32px;color:#BFCDC9\">acceleration (m/s²)</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Push harder → speeds up faster.<br>Heavier object → speeds up slower.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">To find acceleration, flip it around: <b style=\"color:#7FB0F2\">a = F ÷ m</b></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Force &amp; Motion · 6</p>\n\n</section>", "note": "The formula just writes down what students already feel. Pushing an empty shopping cart vs. a full one is the best everyday example. Most problems ask for acceleration, so practice a = F ÷ m."}, {"id": "law2b", "html": "<section id=\"law2b\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY THE NUMBERS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Same push, different mass</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Two carts each pushed with the same orange force arrow; the empty cart has a long blue arrow showing fast speed-up, the loaded cart has a short blue arrow\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"20\" y1=\"70\" x2=\"120\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"116,50 150,70 116,90\" fill=\"#B4521F\"/>\n<rect x=\"160\" y=\"40\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"195\" cy=\"128\" r=\"16\" fill=\"#18262B\"/><circle cx=\"285\" cy=\"128\" r=\"16\" fill=\"#18262B\"/>\n<line x1=\"350\" y1=\"75\" x2=\"640\" y2=\"75\" stroke=\"#2463B8\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"636,53 680,75 636,97\" fill=\"#2463B8\"/>\n<line x1=\"20\" y1=\"300\" x2=\"120\" y2=\"300\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"116,280 150,300 116,320\" fill=\"#B4521F\"/>\n<rect x=\"160\" y=\"270\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<rect x=\"172\" y=\"220\" width=\"64\" height=\"50\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<rect x=\"244\" y=\"220\" width=\"64\" height=\"50\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<rect x=\"208\" y=\"176\" width=\"64\" height=\"44\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<circle cx=\"195\" cy=\"358\" r=\"16\" fill=\"#18262B\"/><circle cx=\"285\" cy=\"358\" r=\"16\" fill=\"#18262B\"/>\n<line x1=\"350\" y1=\"305\" x2=\"440\" y2=\"305\" stroke=\"#2463B8\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"436,283 480,305 436,327\" fill=\"#2463B8\"/>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:30%;text-align:left\">Force</th><th style=\"width:30%;text-align:left\">Mass</th><th style=\"width:40%;text-align:left\">Acceleration</th></tr>\n<tr><td>10 N</td><td>2 kg</td><td><b>5 m/s²</b></td></tr>\n<tr><td>10 N</td><td>5 kg</td><td><b>2 m/s²</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>20 N</b></td><td>5 kg</td><td><b>4 m/s²</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Orange arrows: the push (same size). Blue arrows: how fast each cart speeds up.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 7</p>\n\n</section>", "note": "Cover the last column and let students compute each row with a = F ÷ m: 10 ÷ 2 = 5, 10 ÷ 5 = 2, 20 ÷ 5 = 4. Doubling the force doubles the acceleration."}, {"id": "law3", "html": "<section id=\"law3\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">NEWTON’S THIRD LAW</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Every push gets pushed back</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Two skaters push each other; orange arrows show equal pushes in opposite directions and blue arrows show both skaters sliding apart\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<line x1=\"20\" y1=\"340\" x2=\"620\" y2=\"340\" stroke=\"#9AAAA6\" stroke-width=\"6\"/>\n<circle cx=\"250\" cy=\"110\" r=\"26\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"250\" y1=\"136\" x2=\"250\" y2=\"250\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"170\" x2=\"316\" y2=\"166\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"250\" x2=\"226\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"250\" x2=\"274\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<circle cx=\"390\" cy=\"110\" r=\"26\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"390\" y1=\"136\" x2=\"390\" y2=\"250\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"170\" x2=\"324\" y2=\"166\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"250\" x2=\"366\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"250\" x2=\"414\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"330\" y1=\"60\" x2=\"400\" y2=\"60\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"396,42 430,60 396,78\" fill=\"#B4521F\"/>\n<line x1=\"310\" y1=\"60\" x2=\"240\" y2=\"60\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"244,42 210,60 244,78\" fill=\"#B4521F\"/>\n<line x1=\"180\" y1=\"290\" x2=\"80\" y2=\"290\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"84,272 46,290 84,308\" fill=\"#2463B8\"/>\n<line x1=\"460\" y1=\"290\" x2=\"560\" y2=\"290\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"556,272 594,290 556,308\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Push a friend on skates: you both slide apart.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">When you push something, it pushes back on you <b>just as hard</b>, in the <b>opposite direction</b>.</p>\n<p style=\"font-size:36px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Forces come in pairs: equal size, opposite direction, on two different objects.</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Example: a rocket pushes gas down, and the gas pushes the rocket up.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 8</p>\n\n</section>", "note": "Other examples: when you walk, your foot pushes the ground backward and the ground pushes you forward. When you swim, you push water back and the water pushes you ahead."}, {"id": "pairs", "html": "<section id=\"pairs\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">A COMMON MIX-UP</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Force pair or balanced forces?</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Action–reaction pair</th><th style=\"width:33%;text-align:left\">Balanced forces</th></tr>\n<tr><td>Acts on</td><td><b>Two</b> different objects</td><td><b>One</b> object</td></tr>\n<tr><td>Same size?</td><td>Always</td><td>Yes, when balanced</td></tr>\n<tr><td>Cancel out?</td><td>No (different objects)</td><td>Yes, net force = 0</td></tr>\n<tr style=\"background:#E1ECFA\"><td>Example</td><td>You push the wall, the wall pushes you</td><td>Gravity pulls a book down, the table holds it up</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Quick test:</b> ask “which object does each force act on?” Two objects = a pair. One object = balanced.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 9</p>\n\n</section>", "note": "The book on a table is the classic trap. Gravity and the table’s push both act on the book, so they are balanced forces, not an action–reaction pair. The book’s reaction partner to gravity is the book pulling Earth up."}, {"id": "vt", "html": "<section id=\"vt\" data-section=\"Reading a velocity–time graph\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">VELOCITY–TIME GRAPH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Read motion from a picture</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:860px 1fr;gap:56px;align-items:center;flex:1\">\n<div style=\"position:relative;width:860px;height:560px\">\n<svg aria-label=\"Velocity–time graph: speed rises in a straight line from 0 to 20 meters per second in the first 5 seconds, then stays flat at 20 until 10 seconds; the area under the line is shaded blue\" width=\"860\" height=\"560\" viewBox=\"0 0 860 560\">\n<polygon points=\"120,460 420,140 720,140 720,460\" fill=\"#C9DBF2\"/>\n<line x1=\"120\" y1=\"460\" x2=\"790\" y2=\"460\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<line x1=\"120\" y1=\"460\" x2=\"120\" y2=\"60\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<line x1=\"120\" y1=\"140\" x2=\"720\" y2=\"140\" stroke=\"#9AAAA6\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/>\n<line x1=\"420\" y1=\"460\" x2=\"420\" y2=\"140\" stroke=\"#9AAAA6\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/>\n<polyline points=\"120,460 420,140 720,140\" fill=\"none\" stroke=\"#2463B8\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n</svg>\n<p style=\"position:absolute;left:40px;top:120px;width:70px;font-size:24px;text-align:right\">20</p>\n<p style=\"position:absolute;left:40px;top:440px;width:70px;font-size:24px;text-align:right\">0</p>\n<p style=\"position:absolute;left:400px;top:476px;width:40px;font-size:24px;text-align:center\">5</p>\n<p style=\"position:absolute;left:695px;top:476px;width:50px;font-size:24px;text-align:center\">10</p>\n<p style=\"position:absolute;left:560px;top:516px;width:260px;font-size:24px;color:#4F5F64\">time (s)</p>\n<p style=\"position:absolute;left:0px;top:20px;width:300px;font-size:24px;color:#4F5F64\">speed (m/s)</p>\n<p style=\"position:absolute;left:130px;top:170px;width:170px;font-size:24px;font-weight:800;color:#2463B8\">steeper = bigger acceleration</p>\n<p style=\"position:absolute;left:450px;top:270px;width:240px;font-size:24px;font-weight:800\">blue area = distance</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#2463B8\">Slope</b> of the line = acceleration. A flat line means constant speed.</p>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#2463B8\">Area</b> under the line = distance traveled.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 10</p>\n\n</section>", "note": "Trace the line with your finger: it climbs for 5 seconds (speeding up), then goes flat (steady speed). The next slide works out the numbers."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">A car goes from 0 to 20 m/s in 5 s, then cruises at 20 m/s for 5 s.</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Acceleration (first 5 s)</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">a = 20 ÷ 5<br>&#160;&#160;= 4 m/s²</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Distance: triangle</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">½ × 5 × 20<br>= 50 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Distance: rectangle</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">5 × 20<br>= 100 m</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Total distance in 10 s: 50 + 100 = <span style=\"color:#2463B8\">150 m</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 11</p>\n\n</section>", "note": "This is the graph from the previous slide. Acceleration is the slope: speed rose by 20 m/s in 5 s. Distance is the area: split it into a triangle (speeding up) and a rectangle (steady speed)."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Do heavier objects fall faster?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">A heavy object gets a bigger pull from gravity, but it is also <b>harder to speed up</b> (F = ma). The two effects cancel out.</p>\n<p style=\"font-size:34px;line-height:1.5\">Without air resistance, a hammer and a feather <b>land together</b>. Astronauts showed this on the Moon in 1971.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Force &amp; Motion · 12</p>\n\n</section>", "note": "On Earth a feather falls slowly only because of air resistance. Try it in class: drop a flat sheet of paper and a book (paper falls slowly), then crumple the paper into a ball and drop both again. They land at almost the same time. The Moon demonstration was by Apollo 15 astronaut David Scott."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK · TRUE OR FALSE?</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">A ball rolling on the floor must have a force pushing it the whole time.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">With the same push, a 2 kg cart speeds up faster than a 4 kg cart.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">A horse pulls a cart forward because the cart pulls back on the horse more weakly.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 13</p>\n\n</section>", "note": "Give students one minute. Q3 is the hardest; let them argue about it before revealing the answer."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Inertia keeps it rolling. Friction is what slows it down.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">True</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">a = F ÷ m, so less mass means more acceleration.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">The pair is always equal. The cart moves because the net force on the cart is not zero.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Things keep moving unless a net force acts.<br><span style=\"color:#E58A55\">F = ma, and every force comes in a pair.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Force &amp; Motion · 14</p>\n\n</section>", "note": "For Q3: the horse pulls the cart and the cart pulls the horse with equal force. The cart moves because the horse’s pull on it is bigger than the friction holding it back. The horse moves because the ground pushes it forward harder than the cart pulls it back."}]}, "circuits-zh": {"title": "電路與歐姆定律", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">國中理化零基礎 · 第 2 課</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.1;color:#F3F5F2\">電路與<br>歐姆定律</h1>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#7FB0F2\">Circuits &amp; Ohm’s Law</p>\n<p style=\"font-size:32px;line-height:1.5;color:#BFCDC9\">從零開始：電是怎麼在電線裡跑的？</p>\n</div>\n<svg aria-label=\"一顆電池接著一顆發亮的燈泡，電子沿著電線繞圈\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M90 90 H630 V400 H90 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"60\" y=\"200\" width=\"60\" height=\"80\" fill=\"#18262B\"/>\n<rect x=\"50\" y=\"214\" width=\"80\" height=\"12\" fill=\"#F3F5F2\"/>\n<rect x=\"68\" y=\"250\" width=\"44\" height=\"12\" fill=\"#F3F5F2\"/>\n<circle cx=\"360\" cy=\"90\" r=\"46\" fill=\"#FFC94D\" stroke=\"#F3F5F2\" stroke-width=\"6\"/>\n<path d=\"M340 100 L352 76 L368 100 L380 76\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\" stroke-linejoin=\"round\"/>\n<line x1=\"360\" y1=\"22\" x2=\"360\" y2=\"0\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"420\" y1=\"40\" x2=\"438\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"300\" y1=\"40\" x2=\"282\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"440\" y1=\"90\" x2=\"466\" y2=\"90\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\" opacity=\"0\"/>\n<circle cx=\"200\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"520\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"630\" cy=\"220\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"500\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"300\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"90\" cy=\"340\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過電的同學。我們不背公式，先用水管來想像電路，再看一個很有名的公式，最後解開聖誕燈串的謎題。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一顆燈泡壞了，為什麼整串都熄掉？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">老式聖誕燈串</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">其中一顆燈泡壞掉，<b style=\"color:#18262B\">整串全部一起熄滅</b>，要一顆一顆換才找得到是哪顆壞了。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">家裡的燈和電器</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">房間的燈關掉，<b style=\"color:#18262B\">冰箱、電視照樣運轉</b>，每一個都可以分開開關。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">同樣是接電，差別在<b style=\"color:#B4521F\">「接法」</b>。看完這份簡報，你就知道答案。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 2</p>\n\n</section>", "note": "先讓學生猜：為什麼一個會全滅，一個各管各的？很多人會猜「聖誕燈比較便宜」。答案是接法不同，我們在後半段揭曉。要看懂接法，得先認識電路裡的三個主角。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標 Learning goals</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">認識三個主角</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">說出電壓、電流、電阻各自代表什麼。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">會用 V = IR</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">知道電壓和電阻，就能算出電流。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">分辨串聯與並聯</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">解釋聖誕燈串和家裡電器的差別。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 3</p>\n\n</section>", "note": "三個目標對應簡報的三段：水管比喻、歐姆定律、串聯並聯。最後還有一個常見迷思和三題小測驗。"}, {"id": "water", "html": "<section id=\"water\" data-section=\"用水管比喻認識電壓、電流、電阻三個主角\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">把電路想成水管</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電路就像一圈裝滿水的水管</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"一圈水管，左邊有抽水馬達推水，上方有一段變細的管子，水沿著管子繞圈流動\" width=\"640\" height=\"420\" viewBox=\"0 0 640 420\">\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#9CC0EA\" stroke-width=\"44\" stroke-linejoin=\"round\"/>\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-dasharray=\"18 22\" stroke-linejoin=\"round\"/>\n<rect x=\"250\" y=\"44\" width=\"140\" height=\"52\" fill=\"#E7EEEA\"/>\n<rect x=\"250\" y=\"60\" width=\"140\" height=\"20\" fill=\"#9CC0EA\" stroke=\"#B4521F\" stroke-width=\"5\"/>\n<circle cx=\"80\" cy=\"215\" r=\"62\" fill=\"#18262B\"/>\n<path d=\"M58 245 L80 180 L102 245 Z\" fill=\"#E58A55\"/>\n<polygon points=\"470,345 500,360 470,375\" fill=\"#2463B8\"/>\n<polygon points=\"170,85 140,70 170,55\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">馬達推水，水在管子裡繞圈；上方細管就是燈泡。</p>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:42%;text-align:left\">水管世界</th><th style=\"width:58%;text-align:left\">電路世界</th></tr>\n<tr><td>抽水馬達</td><td><b>電池</b> battery</td></tr>\n<tr><td>水管</td><td><b>電線</b> wire</td></tr>\n<tr><td>管子裡的水</td><td><b>電子</b> electron</td></tr>\n<tr><td>一段變細的管子</td><td><b>燈泡</b>（電阻）bulb</td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">重點：電線裡<b style=\"color:#B4521F\">本來就擠滿電子</b>。電池不是生出電子，而是「推」它們。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 4</p>\n\n</section>", "note": "學生常以為電池會「生出」電。強調：金屬電線裡本來就有大量電子，就像水管本來就裝滿水。電池只是負責推。這一點到最後破解迷思時會再用到。"}, {"id": "three", "html": "<section id=\"three\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電路的三個主角</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#B4521F\">V</p>\n<h3 style=\"font-size:44px;font-weight:700\">電壓 <span style=\"color:#4F5F64\">voltage</span></h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：伏特（V）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>推力</b>：馬達推水的力道，也就是水壓。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">一顆電池 1.5 V，家裡插座約 110 V。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#2463B8\">I</p>\n<h3 style=\"font-size:44px;font-weight:700\">電流 <span style=\"color:#4F5F64\">current</span></h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：安培（A）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>流量</b>：每秒有多少水流過同一個點。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">流得越多，燈泡越亮。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#18262B\">R</p>\n<h3 style=\"font-size:44px;font-weight:700\">電阻 <span style=\"color:#4F5F64\">resistance</span></h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：歐姆（Ω）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>阻擋</b>：管子變細或塞住，水很難通過。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">燈泡就是一個電阻，燈絲被擠得發熱發亮。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 5</p>\n\n</section>", "note": "一句話記住：電壓是推力、電流是流量、電阻是阻擋。英文 voltage、current、resistance。單位分別是伏特、安培、歐姆。"}, {"id": "intuition", "html": "<section id=\"intuition\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先用直覺猜猜看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">推力和阻擋，怎麼影響流量？</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:40px;flex:1;justify-content:center\">\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#F7E6DC;padding:40px 48px;border-radius:20px\">馬達推得更用力<br><span style=\"color:#B4521F\">電壓變大</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E1ECFA;padding:40px 48px;border-radius:20px\">水流變多<br><span style=\"color:#2463B8\">電流變大</span></p>\n</div>\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E4E8E6;padding:40px 48px;border-radius:20px\">管子塞得更嚴重<br><span style=\"color:#18262B\">電阻變大</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E1ECFA;padding:40px 48px;border-radius:20px\">水流變少<br><span style=\"color:#2463B8\">電流變小</span></p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">你剛剛用直覺說出的，正是一條物理定律。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 6</p>\n\n</section>", "note": "先讓學生回答兩個問題再翻出答案：馬達推得更用力，水流會怎樣？管子塞得更嚴重呢？大多數人都答得出來，這就是歐姆定律的直覺。"}, {"id": "law", "html": "<section id=\"law\" data-section=\"歐姆定律 V = IR，並用一題數字慢慢算\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">歐姆定律 Ohm’s Law</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">V</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電壓</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">I</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電流</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">R</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電阻</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">想求電流？<span style=\"color:#7FB0F2\">I = V ÷ R</span>　推力 ÷ 阻擋 = 流量</p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">為什麼電流用 I？它來自法文 intensité（強度），是歷史留下來的習慣。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">電路與歐姆定律 · 7</p>\n\n</section>", "note": "德國科學家歐姆在大約兩百年前，把剛才的直覺寫成公式。公式只有三個字母，不用怕。重點是會倒過來用：要找電流，就用電壓除以電阻。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題 Worked example</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.2\">9 伏特的電池接上 3 歐姆的燈泡，電流是多少？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">寫下已知</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">V = 9 V<br>R = 3 Ω</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">選公式</h3>\n<p style=\"font-size:32px;line-height:1.6\">要找電流，所以用<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">I = V ÷ R</b></p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">代入計算</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">I = 9 ÷ 3<br>&#160;&#160;= 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">加上單位</h3>\n<p style=\"font-size:32px;line-height:1.6\">電流的單位是安培<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">3 A</b></p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">答案：電流是 <span style=\"color:#2463B8\">3 安培</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 8</p>\n\n</section>", "note": "帶學生一步一步做。第一步永遠是先把知道的寫下來，第二步才選公式。最後別忘了單位，電流是安培。"}, {"id": "vary", "html": "<section id=\"vary\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">換你試試</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">只改一個數字，電流會怎麼變？</h2>\n</div>\n<table style=\"font-size:36px;color:#18262B\">\n<tr><th style=\"width:20%;text-align:left\">電池電壓</th><th style=\"width:20%;text-align:left\">燈泡電阻</th><th style=\"width:16%;text-align:left\">電流</th><th style=\"width:44%;text-align:left\">發生了什麼</th></tr>\n<tr><td>9 V</td><td>3 Ω</td><td><b>3 A</b></td><td>原本的例題</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>18 V</b></td><td>3 Ω</td><td><b>6 A</b></td><td>電壓變 2 倍 → 電流也變 2 倍</td></tr>\n<tr style=\"background:#E1ECFA\"><td>9 V</td><td><b>9 Ω</b></td><td><b>1 A</b></td><td>電阻變 3 倍 → 電流變成 1/3</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">公式只是把直覺寫成數學：<br><span style=\"color:#B4521F\">電壓越大，電流越大；電阻越大，電流越小。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 9</p>\n\n</section>", "note": "先遮住電流那一欄，讓學生自己算：18 除以 3 等於 6；9 除以 9 等於 1。再請他們說出規律。"}, {"id": "series", "html": "<section id=\"series\" data-section=\"串聯與並聯：燈泡的兩種接法\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">接法一</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">串聯 series：只有一條路</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"串聯電路：電池和三顆燈泡排在同一圈電線上，中間那顆燈泡壞掉打叉，三顆燈泡全部熄滅\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 90 H690 V360 H70 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"40\" y=\"180\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"196\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"236\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"220\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"380\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"540\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"350\" y1=\"60\" x2=\"410\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"410\" y1=\"60\" x2=\"350\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">中間那顆壞了，三顆全部熄滅。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">燈泡一個接一個排成一條線，像<b>糖葫蘆</b>串在同一根竹籤上。</p>\n<p style=\"font-size:36px;line-height:1.5\">一顆壞掉，就像水管中間被剪斷：<b style=\"color:#B4521F\">整條路不通，全部熄滅</b>。</p>\n<p style=\"font-size:36px;line-height:1.5\">燈泡越多，阻擋加起來越大，<b>每一顆越暗</b>。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：老式聖誕燈串。（現在很多燈串有設計可以繞過壞掉的燈泡。）</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 10</p>\n\n</section>", "note": "回到開場的謎題。串聯只有一條路，水要依序穿過每個燈泡。中間一顆燈絲斷了，整圈都流不動，所以全部熄滅。"}, {"id": "parallel", "html": "<section id=\"parallel\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">接法二</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">並聯 parallel：很多條路</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"並聯電路：電池接出上下兩條主線，中間分出三條分支各接一顆燈泡；中間分支的燈泡壞掉打叉，左右兩顆仍然發亮\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 60 H690 M70 360 H690 M70 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M260 60 V360 M460 60 V360 M660 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\"/>\n<rect x=\"40\" y=\"160\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"176\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"216\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"260\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"460\" cy=\"210\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"660\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"430\" y1=\"180\" x2=\"490\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"490\" y1=\"180\" x2=\"430\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">中間那顆壞了，左右兩顆照樣亮。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">從主線分出很多條分支，像高速公路的<b>交流道</b>，每條分支各接一顆燈泡。</p>\n<p style=\"font-size:36px;line-height:1.5\">一條分支壞了，只有那條沒電：<b style=\"color:#2463B8\">其他照樣亮</b>。</p>\n<p style=\"font-size:36px;line-height:1.5\">每條分支都直接接到電池兩端，<b>每顆燈泡都拿到全部的電壓</b>。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：家裡的燈、冰箱、電視，教室裡的日光燈。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 11</p>\n\n</section>", "note": "關掉房間的燈，冰箱不會停，這不是理所當然，而是因為家裡的電器刻意用並聯接法。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">串聯和並聯，差在哪裡？</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">比較</th><th style=\"width:32%;text-align:left\">串聯（糖葫蘆）</th><th style=\"width:32%;text-align:left\">並聯（交流道）</th></tr>\n<tr><td>電流的路有幾條</td><td>一條</td><td>很多條</td></tr>\n<tr><td>一顆燈泡壞掉</td><td><span style=\"color:#B4521F\">全部熄滅</span></td><td><span style=\"color:#2463B8\">其他照樣亮</span></td></tr>\n<tr><td>每顆燈泡的電壓</td><td>大家平分</td><td>全部的電壓</td></tr>\n<tr><td>兩顆相同燈泡的亮度</td><td>比較暗</td><td>比較亮</td></tr>\n<tr><td>生活例子</td><td>老式聖誕燈串</td><td>家裡的電器</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:36px;font-weight:700;line-height:1.4\">一句話記住：串聯是「一條路，一個壞全部停」；並聯是「很多條路，各管各的」。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 12</p>\n\n</section>", "note": "亮度題先讓學生預測：兩顆一樣的燈泡接同一顆電池，並聯的每顆燈泡拿到全部電壓，串聯的要平分，所以並聯比較亮。"}, {"id": "breaker", "html": "<section id=\"breaker\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:32px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">延伸題：跳電是因為串聯嗎？不是！</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">為什麼家裡會跳電？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1.25fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:700\">原因一：電器開太多</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">家裡電器是並聯。每多開一台，就多一條分支，總電流就變大。</p>\n<table style=\"font-size:26px;color:#18262B\">\n<tr><th style=\"width:62%;text-align:left\">同時開（110 V）</th><th style=\"width:38%;text-align:right\">電流</th></tr>\n<tr><td>吹風機 1500 W</td><td style=\"text-align:right\">約 13.6 A</td></tr>\n<tr><td>電熱水壺 1200 W</td><td style=\"text-align:right\">約 10.9 A</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>合計：超過 20 A 上限，跳電</b></td><td style=\"text-align:right\"><b>約 24.5 A</b></td></tr>\n</table>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:700\">原因二：短路</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">電線直接碰在一起，電流不經過電器，電阻幾乎是 0。</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:36px;font-weight:700;line-height:1.5\">I = V ÷ R<br>R ≈ 0 → I 暴增</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">斷路器馬上切斷，避免電線過熱起火。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#E1ECFA;padding:24px 32px;border-radius:16px\"><b>電器之間是並聯</b>，所以能各自開關；<b>斷路器跟整條迴路串聯</b>，所以一跳，整條迴路全部斷電。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 13</p>\n\n</section>", "note": "很多學生以為跳電是因為串聯，其實相反。瓦數換算成電流用的是「電流 = 瓦數 ÷ 電壓」，例如 1500 ÷ 110 約 13.6 安培；這裡只要看懂合計超過上限就好。表中瓦數是常見電器的大約值，實際以電器標示為準；20 安培是常見的單一迴路上限，各家配電不同。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電流流過燈泡之後，會變少嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.1\">不會。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:36px;line-height:1.5\">串聯電路裡，燈泡前面和後面的電流<b>一樣大</b>。燈泡用掉的是電子帶的<b>能量</b> energy，不是電子本身。</p>\n<p style=\"font-size:36px;line-height:1.5\">就像水流過水車：水車轉了，<b>水一滴也沒少</b>。電池「沒電」是能量用完了，不是電子跑光了。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">電路與歐姆定律 · 14</p>\n\n</section>", "note": "回扣第 4 張：電線裡本來就擠滿電子，電池只是推它們。電池給電子能量，燈泡把能量變成光和熱，電子繼續繞圈回到電池。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗 Quick check</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:36px;line-height:1.5\">電壓、電流、電阻，哪一個是「推力」？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:36px;line-height:1.5\">6 伏特的電池接上 2 歐姆的燈泡，電流是多少？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:36px;line-height:1.5\">教室的燈壞了一支，其他照樣亮。它們是串聯還是並聯？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 15</p>\n\n</section>", "note": "給學生 1 分鐘作答。Q2 提醒他們先寫已知、再選公式、最後加單位。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:700\">電壓</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">電壓是推力，電流是流量，電阻是阻擋。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:700\">3 安培</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">I = V ÷ R = 6 ÷ 2 = 3 A</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:700\">並聯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">很多條路，各管各的。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:56px;font-weight:900;line-height:1.35\">電壓推、電阻擋、電流流。<br><span style=\"color:#E58A55\">燈泡用掉的是能量，不是電流。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">電路與歐姆定律 · 16</p>\n\n</section>", "note": "下一課：波動、聲音與光。為什麼聽得到隔壁講話，卻看不到人？"}]}, "circuits-en": {"title": "Circuits & Ohm’s Law", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS FROM ZERO · LESSON 2</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Circuits &amp;<br>Ohm’s Law</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">How does electricity move through a wire?</p>\n</div>\n<svg aria-label=\"A battery connected to a glowing light bulb, with electrons moving around the wire loop\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M90 90 H630 V400 H90 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"60\" y=\"200\" width=\"60\" height=\"80\" fill=\"#18262B\"/>\n<rect x=\"50\" y=\"214\" width=\"80\" height=\"12\" fill=\"#F3F5F2\"/>\n<rect x=\"68\" y=\"250\" width=\"44\" height=\"12\" fill=\"#F3F5F2\"/>\n<circle cx=\"360\" cy=\"90\" r=\"46\" fill=\"#FFC94D\" stroke=\"#F3F5F2\" stroke-width=\"6\"/>\n<path d=\"M340 100 L352 76 L368 100 L380 76\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\" stroke-linejoin=\"round\"/>\n<line x1=\"360\" y1=\"22\" x2=\"360\" y2=\"0\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"420\" y1=\"40\" x2=\"438\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"300\" y1=\"40\" x2=\"282\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<circle cx=\"200\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"520\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"630\" cy=\"220\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"500\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"300\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"90\" cy=\"340\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied electricity. We skip memorizing formulas at first: we picture a circuit as water pipes, then meet one famous formula, and finally solve the string-lights puzzle."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">One bulb breaks. Why does the whole string go dark?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Old holiday lights</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">One bulb burns out and <b style=\"color:#18262B\">the whole string goes dark</b>. You have to test bulbs one by one to find it.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Lights at home</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Turn off the bedroom light and <b style=\"color:#18262B\">the fridge and TV keep running</b>. Each one switches on its own.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Both are plugged into electricity. The difference is <b style=\"color:#B4521F\">how they are wired</b>.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 2</p>\n\n</section>", "note": "Let students guess first. Many say “holiday lights are cheaper.” The real answer is the wiring, which we reveal in the second half. First we need to meet the three main characters of a circuit."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Name the big three</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Explain voltage, current and resistance.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use V = IR</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Find the current from the voltage and resistance.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Series vs. parallel</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Explain holiday lights vs. home wiring.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 3</p>\n\n</section>", "note": "The three goals match the three parts of the deck: the water-pipe model, Ohm’s law, and series vs. parallel. We finish with a myth and a three-question quiz."}, {"id": "water", "html": "<section id=\"water\" data-section=\"Water pipes as a model for voltage, current and resistance\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">THINK OF WATER PIPES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A circuit is like a loop of pipe</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A closed loop of pipe; a pump on the left pushes water around; a narrow section at the top is the bulb\" width=\"640\" height=\"420\" viewBox=\"0 0 640 420\">\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#9CC0EA\" stroke-width=\"44\" stroke-linejoin=\"round\"/>\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-dasharray=\"18 22\" stroke-linejoin=\"round\"/>\n<rect x=\"250\" y=\"44\" width=\"140\" height=\"52\" fill=\"#E7EEEA\"/>\n<rect x=\"250\" y=\"60\" width=\"140\" height=\"20\" fill=\"#9CC0EA\" stroke=\"#B4521F\" stroke-width=\"5\"/>\n<circle cx=\"80\" cy=\"215\" r=\"62\" fill=\"#18262B\"/>\n<path d=\"M58 245 L80 180 L102 245 Z\" fill=\"#E58A55\"/>\n<polygon points=\"470,345 500,360 470,375\" fill=\"#2463B8\"/>\n<polygon points=\"170,85 140,70 170,55\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The pump pushes water around. The narrow part is the bulb.</p>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:45%;text-align:left\">Water world</th><th style=\"width:55%;text-align:left\">Circuit world</th></tr>\n<tr><td>Pump</td><td><b>Battery</b></td></tr>\n<tr><td>Pipe</td><td><b>Wire</b></td></tr>\n<tr><td>Water in the pipe</td><td><b>Electrons</b></td></tr>\n<tr><td>A narrow section</td><td><b>Bulb</b> (a resistor)</td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Key idea: wires are <b style=\"color:#B4521F\">already full of electrons</b>. A battery doesn’t make them; it pushes them.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 4</p>\n\n</section>", "note": "Students often think a battery “creates” electricity. Stress that metal wires already hold huge numbers of electrons, just as a pipe is already full of water. The battery only pushes. We come back to this when we bust the myth at the end."}, {"id": "three", "html": "<section id=\"three\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">The three main characters</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#B4521F\">V</p>\n<h3 style=\"font-size:44px;font-weight:800\">Voltage</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: volt (V)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The push.</b> How hard the pump pushes the water.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">An AA battery is 1.5 V. A US wall outlet is about 120 V.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#2463B8\">I</p>\n<h3 style=\"font-size:44px;font-weight:800\">Current</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: ampere (A)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The flow.</b> How much water passes one point each second.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">More flow makes a bulb brighter.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#18262B\">R</p>\n<h3 style=\"font-size:44px;font-weight:800\">Resistance</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: ohm (Ω)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The blockage.</b> A narrow or clogged pipe that slows the water.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">A bulb is a resistor: its thin filament heats up and glows.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 5</p>\n\n</section>", "note": "One line to remember: voltage is the push, current is the flow, resistance is the blockage. Units: volts, amps, ohms."}, {"id": "intuition", "html": "<section id=\"intuition\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">GUESS FIRST</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">How do push and blockage change the flow?</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:40px;flex:1;justify-content:center\">\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#F7E6DC;padding:40px 48px;border-radius:20px\">Pump pushes harder<br><span style=\"color:#B4521F\">voltage goes up</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E1ECFA;padding:40px 48px;border-radius:20px\">More water flows<br><span style=\"color:#2463B8\">current goes up</span></p>\n</div>\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E4E8E6;padding:40px 48px;border-radius:20px\">Pipe gets more clogged<br><span style=\"color:#18262B\">resistance goes up</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E1ECFA;padding:40px 48px;border-radius:20px\">Less water flows<br><span style=\"color:#2463B8\">current goes down</span></p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">What you just guessed is a law of physics.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 6</p>\n\n</section>", "note": "Ask both questions before revealing: if the pump pushes harder, what happens to the flow? If the pipe gets more clogged? Almost everyone gets these right. That intuition is Ohm’s law."}, {"id": "law", "html": "<section id=\"law\" data-section=\"Ohm’s law V = IR, worked step by step\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">OHM’S LAW</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">V</p>\n<p style=\"font-size:32px;color:#BFCDC9\">voltage</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">I</p>\n<p style=\"font-size:32px;color:#BFCDC9\">current</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">R</p>\n<p style=\"font-size:32px;color:#BFCDC9\">resistance</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Need the current? <span style=\"color:#7FB0F2\">I = V ÷ R</span> (push ÷ blockage = flow)</p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">Why “I” for current? It comes from the French word intensité (intensity). It’s just a tradition.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Circuits &amp; Ohm’s Law · 7</p>\n\n</section>", "note": "Georg Ohm, a German scientist, wrote this intuition down as a formula about 200 years ago. It only has three letters. The key skill is flipping it: to find current, divide voltage by resistance."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">A 9 V battery is connected to a 3 Ω bulb. What is the current?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Write what you know</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">V = 9 V<br>R = 3 Ω</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Pick the formula</h3>\n<p style=\"font-size:30px;line-height:1.6\">We want current, so<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">I = V ÷ R</b></p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Plug in and solve</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">I = 9 ÷ 3<br>&#160;&#160;= 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Add the unit</h3>\n<p style=\"font-size:30px;line-height:1.6\">Current is in amps<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">3 A</b></p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Answer: the current is <span style=\"color:#2463B8\">3 amps</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 8</p>\n\n</section>", "note": "Walk through it step by step. Step one is always writing down what you know; only then choose the formula. Don’t forget the unit: current is measured in amps."}, {"id": "vary", "html": "<section id=\"vary\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">YOUR TURN</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Change one number. What happens?</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:20%;text-align:left\">Battery</th><th style=\"width:20%;text-align:left\">Bulb</th><th style=\"width:16%;text-align:left\">Current</th><th style=\"width:44%;text-align:left\">What changed</th></tr>\n<tr><td>9 V</td><td>3 Ω</td><td><b>3 A</b></td><td>The original example</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>18 V</b></td><td>3 Ω</td><td><b>6 A</b></td><td>Voltage ×2 → current ×2</td></tr>\n<tr style=\"background:#E1ECFA\"><td>9 V</td><td><b>9 Ω</b></td><td><b>1 A</b></td><td>Resistance ×3 → current ÷3</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">The formula just writes down your intuition:<br><span style=\"color:#B4521F\">more voltage, more current; more resistance, less current.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 9</p>\n\n</section>", "note": "Cover the current column and let students work it out: 18 ÷ 3 = 6 and 9 ÷ 9 = 1. Then ask them to state the pattern in their own words."}, {"id": "series", "html": "<section id=\"series\" data-section=\"Series vs. parallel: two ways to wire bulbs\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WIRING STYLE 1</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Series: only one path</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Series circuit: a battery and three bulbs on one loop of wire; the middle bulb is broken and crossed out, and all three bulbs are dark\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 90 H690 V360 H70 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"40\" y=\"180\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"196\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"236\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"220\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"380\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"540\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"350\" y1=\"60\" x2=\"410\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"410\" y1=\"60\" x2=\"350\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The middle bulb broke, so all three went dark.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">Bulbs are lined up one after another, like <b>beads on a single string</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">One breaks and it’s like cutting the pipe: <b style=\"color:#B4521F\">the whole loop stops</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">More bulbs add more resistance, so <b>each bulb gets dimmer</b>.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Example: old holiday lights. (Many newer strings have a bypass so one dead bulb doesn’t kill the rest.)</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 10</p>\n\n</section>", "note": "Back to the opening puzzle. In series there is only one path, so the water has to pass through every bulb in turn. When one filament breaks, the whole loop stops flowing and every bulb goes dark."}, {"id": "parallel", "html": "<section id=\"parallel\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WIRING STYLE 2</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Parallel: many paths</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Parallel circuit: a battery feeds a top and bottom wire with three branches between them, each with its own bulb; the middle bulb is broken and crossed out while the other two still glow\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 60 H690 M70 360 H690 M70 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M260 60 V360 M460 60 V360 M660 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\"/>\n<rect x=\"40\" y=\"160\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"176\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"216\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"260\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"460\" cy=\"210\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"660\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"430\" y1=\"180\" x2=\"490\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"490\" y1=\"180\" x2=\"430\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The middle bulb broke; the other two still glow.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">The main wire splits into branches, like <b>exits off a highway</b>. Each branch has its own bulb.</p>\n<p style=\"font-size:34px;line-height:1.5\">If one branch breaks, only that branch stops: <b style=\"color:#2463B8\">the others stay on</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">Every branch connects straight to the battery, so <b>each bulb gets the full voltage</b>.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Examples: lights, fridge and TV at home; classroom ceiling lights.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 11</p>\n\n</section>", "note": "Turning off the bedroom light doesn’t stop the fridge. That isn’t automatic; it’s because home appliances are deliberately wired in parallel."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Series vs. parallel</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">Compare</th><th style=\"width:32%;text-align:left\">Series (one string)</th><th style=\"width:32%;text-align:left\">Parallel (highway exits)</th></tr>\n<tr><td>Number of paths</td><td>One</td><td>Many</td></tr>\n<tr><td>One bulb breaks</td><td><span style=\"color:#B4521F\">All go dark</span></td><td><span style=\"color:#2463B8\">Others stay on</span></td></tr>\n<tr><td>Voltage per bulb</td><td>Shared</td><td>Full voltage</td></tr>\n<tr><td>Two identical bulbs</td><td>Dimmer</td><td>Brighter</td></tr>\n<tr><td>Everyday example</td><td>Old holiday lights</td><td>Home appliances</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:36px;font-weight:800;line-height:1.4\">Remember: series is “one path, one breaks, all stop.” Parallel is “many paths, each on its own.”</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 12</p>\n\n</section>", "note": "Ask students to predict the brightness row first: two identical bulbs on the same battery. In parallel each bulb gets the full voltage; in series they share it, so parallel bulbs are brighter."}, {"id": "breaker", "html": "<section id=\"breaker\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:32px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BONUS: IS IT BECAUSE OF SERIES? NO!</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why does a breaker trip?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1.25fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:800\">Cause 1: too much at once</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Home appliances are in parallel. Each one adds a branch, so the total current goes up.</p>\n<table style=\"font-size:26px;color:#18262B\">\n<tr><th style=\"width:62%;text-align:left\">Running together (120 V)</th><th style=\"width:38%;text-align:right\">Current</th></tr>\n<tr><td>Hair dryer, 1500 W</td><td style=\"text-align:right\">12.5 A</td></tr>\n<tr><td>Electric kettle, 1200 W</td><td style=\"text-align:right\">10 A</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>Total: over the 20 A limit, trips</b></td><td style=\"text-align:right\"><b>22.5 A</b></td></tr>\n</table>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:800\">Cause 2: a short circuit</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Two wires touch, the current skips the appliance, and resistance drops to almost zero.</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:36px;font-weight:700;line-height:1.5\">I = V ÷ R<br>R ≈ 0 → I spikes</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">The breaker cuts power before the wires overheat.</p>\n</div>\n</div>\n<p style=\"font-size:30px;line-height:1.5;background:#E1ECFA;padding:20px 32px;border-radius:16px\"><b>Appliances are in parallel</b>, so each switches on its own. <b>The breaker is in series</b> with the whole circuit, so when it trips, everything on that circuit goes off.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 13</p>\n\n</section>", "note": "Many students think breakers trip because of series wiring, or because “there isn’t enough electricity.” Both are wrong: the outlet supplies a fixed voltage, and the appliances decide how much current flows. To convert watts to amps, divide by the voltage: 1500 ÷ 120 = 12.5 A. The wattages are typical values; check each appliance’s label. 15 A and 20 A are common limits for a single US household circuit."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does a bulb use up current?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">In a series circuit the current is <b>the same before and after</b> the bulb. The bulb uses up the electrons’ <b>energy</b>, not the electrons.</p>\n<p style=\"font-size:34px;line-height:1.5\">Like water turning a waterwheel: the wheel spins, but <b>not one drop is lost</b>. A “dead” battery has run out of energy, not electrons.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Circuits &amp; Ohm’s Law · 14</p>\n\n</section>", "note": "Link back to slide 4: wires are already full of electrons and the battery only pushes them. The battery gives electrons energy, the bulb turns that energy into light and heat, and the electrons keep circling back to the battery."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">Voltage, current or resistance: which one is the “push”?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">A 6 V battery is connected to a 2 Ω bulb. What is the current?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">One classroom light burns out and the rest stay on. Series or parallel?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 15</p>\n\n</section>", "note": "Give students one minute. For Q2, remind them: write what you know, pick the formula, then add the unit."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">Voltage</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Voltage pushes, current flows, resistance blocks.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">3 amps</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">I = V ÷ R = 6 ÷ 2 = 3 A</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Parallel</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Many paths, each on its own.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Voltage pushes, resistance blocks, current flows.<br><span style=\"color:#E58A55\">A bulb uses up energy, not current.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Circuits &amp; Ohm’s Law · 16</p>\n\n</section>", "note": "Next lesson: waves, sound and light. Why can you hear someone through a wall but not see them?"}]}, "waves-zh": {"title": "波動、聲音與光", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">國中理化零基礎 · 第 3 課</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.1;color:#F3F5F2\">波動、<br>聲音與光</h1>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#7FB0F2\">Waves, Sound &amp; Light</p>\n<p style=\"font-size:32px;line-height:1.5;color:#BFCDC9\">從零開始：聲音和光是怎麼跑到你身邊的？</p>\n</div>\n<svg aria-label=\"三條波：上方是橘色長波，中間是藍色短波，下方是一束黃色光線穿過透鏡聚在一點\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M20 110 C 110 20, 200 20, 290 110 S 470 200, 560 110 S 650 20, 700 70\" fill=\"none\" stroke=\"#E58A55\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M20 250 C 60 200, 100 200, 140 250 S 220 300, 260 250 S 340 200, 380 250 S 460 300, 500 250 S 580 200, 620 250 S 680 290, 700 270\" fill=\"none\" stroke=\"#7FB0F2\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"20\" y1=\"350\" x2=\"330\" y2=\"350\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"400\" x2=\"330\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"450\" x2=\"330\" y2=\"450\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"350\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"450\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"400\" x2=\"700\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\" opacity=\"0.5\"/>\n<ellipse cx=\"330\" cy=\"400\" rx=\"22\" ry=\"70\" fill=\"#7FB0F2\" opacity=\"0.55\" stroke=\"#F3F5F2\" stroke-width=\"4\"/>\n<circle cx=\"560\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "第三課從「波」開始。聲音和光都是波，只是個性不同。我們先認識波，再分別看聲音和光，最後學會判斷凸透鏡會成什麼樣的像。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">為什麼聽得到隔壁講話，卻看不到人？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">聲音</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">可以從門縫鑽過來、繞過轉角，<b style=\"color:#18262B\">隔著牆也聽得到</b>。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">光</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">幾乎只走直線，<b style=\"color:#18262B\">被牆擋住就過不來</b>，所以看不到隔壁的人。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">聲音和光其實都是<b style=\"color:#B4521F\">「波」</b>，只是個性不同。今天就來認識它們。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 2</p>\n\n</section>", "note": "先讓學生猜原因。答案和「波長」有關：聲波的波長大約幾十公分到幾公尺，跟門縫、轉角差不多大，所以容易繞過去；光的波長非常非常短，所以幾乎只走直線。學完波長之後再回來看這題。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標 Learning goals</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">看懂一個波</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">說出波長、頻率，並用 v = fλ 算波速。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">認識聲音</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">分辨聲音三要素，知道聲音為什麼需要介質。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">判斷成像</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">依物距說出凸透鏡會成什麼樣的像。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 3</p>\n\n</section>", "note": "三個目標對應三段：波的基本概念、聲音、光與透鏡。最後有迷思破解和三題小測驗。"}, {"id": "wave", "html": "<section id=\"wave\" data-section=\"什麼是波：波長、頻率與波速\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">什麼是波 wave</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">波傳的是能量，不是東西</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"體育館人浪：一排人，中間幾個人站起來舉手，其他人坐著；箭頭表示人浪往右傳，但每個人都留在原位\" width=\"1600\" height=\"300\" viewBox=\"0 0 1600 300\">\n<line x1=\"40\" y1=\"270\" x2=\"1560\" y2=\"270\" stroke=\"#9AAAA6\" stroke-width=\"6\"/>\n<g fill=\"#4F5F64\">\n<circle cx=\"100\" cy=\"200\" r=\"22\"/><rect x=\"80\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"220\" cy=\"200\" r=\"22\"/><rect x=\"200\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"340\" cy=\"200\" r=\"22\"/><rect x=\"320\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"460\" cy=\"190\" r=\"22\"/><rect x=\"440\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n</g>\n<g fill=\"#B4521F\">\n<circle cx=\"580\" cy=\"150\" r=\"22\"/><rect x=\"560\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"580\" y1=\"128\" x2=\"580\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"700\" cy=\"110\" r=\"22\"/><rect x=\"680\" y=\"132\" width=\"40\" height=\"138\" rx=\"10\"/><line x1=\"700\" y1=\"88\" x2=\"700\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"820\" cy=\"150\" r=\"22\"/><rect x=\"800\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"820\" y1=\"128\" x2=\"820\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n</g>\n<g fill=\"#4F5F64\">\n<circle cx=\"940\" cy=\"190\" r=\"22\"/><rect x=\"920\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n<circle cx=\"1060\" cy=\"200\" r=\"22\"/><rect x=\"1040\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1180\" cy=\"200\" r=\"22\"/><rect x=\"1160\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1300\" cy=\"200\" r=\"22\"/><rect x=\"1280\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n</g>\n<line x1=\"1380\" y1=\"120\" x2=\"1520\" y2=\"120\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"1520,96 1560,120 1520,144\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">體育館的人浪：「站起來」這個動作往右傳，但每個人都留在自己的座位上。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">波是一個<b>振動</b>，一個推一個地傳出去。傳過去的是<b style=\"color:#B4521F\">能量</b>，東西本身沒有跟著跑。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">例子：丟石頭到池塘，漣漪往外擴散，但水面上的葉子只是<b>上下晃</b>，不會被沖走。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 4</p>\n\n</section>", "note": "可以請全班做一次人浪。重點是：每個人只是站起來再坐下，沒有離開座位，但「站起來」這個動作卻傳到了教室另一頭。這就是波：傳能量，不傳東西。"}, {"id": "parts", "html": "<section id=\"parts\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一個波的三個重點</h2>\n<svg aria-label=\"一條波浪線：橘色括號標出兩個波峰之間的距離是波長，藍色直線標出波峰到中線的高度是振幅\" width=\"1664\" height=\"250\" viewBox=\"0 0 1664 250\">\n<line x1=\"0\" y1=\"170\" x2=\"1560\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<path d=\"M0 170 C 80 50, 170 50, 250 170 S 420 290, 500 170 S 670 50, 750 170 S 920 290, 1000 170 S 1170 50, 1250 170 S 1420 290, 1500 170\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"125\" y1=\"30\" x2=\"625\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"125\" y1=\"12\" x2=\"125\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"625\" y1=\"12\" x2=\"625\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"1125\" y1=\"82\" x2=\"1125\" y2=\"170\" stroke=\"#2463B8\" stroke-width=\"10\"/>\n<polygon points=\"1112,96 1125,74 1138,96\" fill=\"#2463B8\"/>\n</svg>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">波長 <span style=\"color:#B4521F\">λ</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">wavelength · 單位：公尺 m</p>\n<p style=\"font-size:32px;line-height:1.5\">相鄰兩個<b>波峰</b>之間的距離（橘色括號）。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">振幅</h3>\n<p style=\"font-size:24px;color:#4F5F64\">amplitude</p>\n<p style=\"font-size:32px;line-height:1.5\">波峰離中線<b>有多高</b>（藍色線）。振幅越大，能量越大。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">頻率 <span style=\"color:#4F5F64\">f</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">frequency · 單位：赫茲 Hz</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>每秒振動幾次</b>。100 Hz 就是每秒振動 100 次。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 5</p>\n\n</section>", "note": "波長和振幅可以在圖上直接看到；頻率要用時間來看，就是每秒鐘有幾個波經過。用跳繩舉例：甩得越快，頻率越高；甩得越用力、繩子晃得越高，振幅越大。"}, {"id": "speed", "html": "<section id=\"speed\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">波速公式 Wave speed</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">v</p>\n<p style=\"font-size:32px;color:#BFCDC9\">波速 m/s</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">f</p>\n<p style=\"font-size:32px;color:#BFCDC9\">頻率 Hz</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">λ</p>\n<p style=\"font-size:32px;color:#BFCDC9\">波長 m</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">例：空氣中聲速約 340 m/s，170 Hz 的聲音<br>波長 λ = v ÷ f = 340 ÷ 170 = <span style=\"color:#E58A55\">2 公尺</span></p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">同一種波、同一個介質裡波速不變：頻率越高，波長就越短。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">波動、聲音與光 · 6</p>\n\n</section>", "note": "可以這樣理解：每秒振動 f 次，每次前進一個波長 λ，所以每秒前進 f × λ。和第 2 課的歐姆定律一樣，三個量知道兩個就能算第三個。聲速 340 m/s 大約是 15°C 空氣中的值。"}, {"id": "kinds", "html": "<section id=\"kinds\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">波的兩種樣子</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">橫波和縱波</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">橫波 <span style=\"color:#4F5F64\">transverse</span></h3>\n<svg aria-label=\"橫波：一條繩子上下起伏，藍色箭頭表示往右傳，橘色箭頭表示繩子上下振動\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<path d=\"M20 100 C 70 20, 120 20, 170 100 S 270 180, 320 100 S 420 20, 470 100 S 570 180, 620 100\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"95\" y1=\"70\" x2=\"95\" y2=\"150\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"84,74 95,54 106,74\" fill=\"#B4521F\"/>\n<polygon points=\"84,146 95,166 106,146\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">像甩繩子：繩子<b style=\"color:#B4521F\">上下</b>振動，波往<b style=\"color:#2463B8\">右</b>傳，兩個方向互相垂直。</p>\n<p style=\"font-size:28px;color:#4F5F64\">例子：繩波、<b style=\"color:#18262B\">光</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">縱波 <span style=\"color:#4F5F64\">longitudinal</span></h3>\n<svg aria-label=\"縱波：一排直線有的擠在一起、有的分得很開，像彈簧被推拉；藍色箭頭表示往右傳，橘色雙箭頭表示前後振動\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<g stroke=\"#18262B\" stroke-width=\"6\">\n<line x1=\"30\" y1=\"50\" x2=\"30\" y2=\"150\"/><line x1=\"48\" y1=\"50\" x2=\"48\" y2=\"150\"/><line x1=\"64\" y1=\"50\" x2=\"64\" y2=\"150\"/><line x1=\"78\" y1=\"50\" x2=\"78\" y2=\"150\"/>\n<line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"150\"/><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"150\"/><line x1=\"220\" y1=\"50\" x2=\"220\" y2=\"150\"/>\n<line x1=\"256\" y1=\"50\" x2=\"256\" y2=\"150\"/><line x1=\"274\" y1=\"50\" x2=\"274\" y2=\"150\"/><line x1=\"290\" y1=\"50\" x2=\"290\" y2=\"150\"/><line x1=\"304\" y1=\"50\" x2=\"304\" y2=\"150\"/>\n<line x1=\"346\" y1=\"50\" x2=\"346\" y2=\"150\"/><line x1=\"396\" y1=\"50\" x2=\"396\" y2=\"150\"/><line x1=\"446\" y1=\"50\" x2=\"446\" y2=\"150\"/>\n<line x1=\"482\" y1=\"50\" x2=\"482\" y2=\"150\"/><line x1=\"500\" y1=\"50\" x2=\"500\" y2=\"150\"/><line x1=\"516\" y1=\"50\" x2=\"516\" y2=\"150\"/><line x1=\"530\" y1=\"50\" x2=\"530\" y2=\"150\"/>\n<line x1=\"572\" y1=\"50\" x2=\"572\" y2=\"150\"/><line x1=\"620\" y1=\"50\" x2=\"620\" y2=\"150\"/>\n</g>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"150\" y1=\"180\" x2=\"250\" y2=\"180\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"152,169 132,180 152,191\" fill=\"#B4521F\"/>\n<polygon points=\"248,169 268,180 248,191\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">像推拉彈簧：彈簧<b style=\"color:#B4521F\">前後</b>擠壓、拉開，波也往<b style=\"color:#2463B8\">右</b>傳，兩個方向相同。</p>\n<p style=\"font-size:28px;color:#4F5F64\">例子：彈簧波、<b style=\"color:#18262B\">聲音</b></p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 7</p>\n\n</section>", "note": "用 Slinky 彈簧示範最清楚：左右甩是橫波，前後推是縱波。聲音是空氣分子前後擠壓的縱波，光則是橫波。"}, {"id": "sound3", "html": "<section id=\"sound3\" data-section=\"聲音：三要素與介質\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">聲音 Sound</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">聲音的三要素</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:24%;text-align:left\">要素</th><th style=\"width:34%;text-align:left\">由什麼決定</th><th style=\"width:42%;text-align:left\">生活例子</th></tr>\n<tr><td><b>響度</b> loudness</td><td><span style=\"color:#2463B8\">振幅</span>：越大越大聲</td><td>輕聲說話 vs. 大聲喊叫</td></tr>\n<tr><td><b>音調</b> pitch</td><td><span style=\"color:#B4521F\">頻率</span>：越高越尖</td><td>小鳥叫（高）vs. 打大鼓（低）</td></tr>\n<tr><td><b>音色</b> timbre</td><td>波形：每種樂器不同</td><td>鋼琴和小提琴彈同一個音，還是聽得出差別</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">人耳大約聽得到 <b>20–20,000 Hz</b> 的聲音。比這更高的叫超音波，狗和蝙蝠聽得到。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 8</p>\n\n</section>", "note": "連回上一段：振幅決定大不大聲，頻率決定高不高音。可以用手機的頻率產生器 App 從低頻慢慢調高，讓學生聽音調變化。"}, {"id": "medium", "html": "<section id=\"medium\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">聲音需要介質 medium</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">太空中聽得到爆炸聲嗎？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:56px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:96px;font-weight:900;line-height:1.1;color:#B4521F\">聽不到。</p>\n<p style=\"font-size:32px;line-height:1.5\">聲音靠介質裡的粒子<b>一個推一個</b>傳過去。太空是真空，沒有粒子可以推，聲音就傳不出去。</p>\n<p style=\"font-size:32px;line-height:1.5\">光不需要介質，所以太陽光可以穿過太空照到地球。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:50%;text-align:left\">在什麼裡面</th><th style=\"width:50%;text-align:right\">傳播速度（約）</th></tr>\n<tr><td>空氣中的聲音</td><td style=\"text-align:right\">340 m/s</td></tr>\n<tr><td>水中的聲音</td><td style=\"text-align:right\">1,500 m/s</td></tr>\n<tr><td>鋼鐵中的聲音</td><td style=\"text-align:right\">5,000 m/s</td></tr>\n<tr style=\"background:#E1ECFA\"><td><b>光</b></td><td style=\"text-align:right\"><b>300,000,000 m/s</b></td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">光比聲音快得多，所以打雷時<b style=\"color:#18262B\">先看到閃電，才聽到雷聲</b>。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 9</p>\n\n</section>", "note": "電影裡太空爆炸「轟」的一聲是音效，真實的太空是安靜的。延伸：從看到閃電到聽到雷聲數幾秒，乘以 340，大約就是閃電離你幾公尺。數值都是約略值，聲速會隨溫度和材料改變。"}, {"id": "reflect", "html": "<section id=\"reflect\" data-section=\"光：反射、折射與凸透鏡成像\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">光 Light</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">光的反射 reflection</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"光的反射：一道光斜斜打到鏡面後反彈出去，中間虛線是法線，左右兩個角度一樣大\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<rect x=\"60\" y=\"340\" width=\"640\" height=\"24\" fill=\"#9CC0EA\" stroke=\"#2463B8\" stroke-width=\"4\"/>\n<line x1=\"60\" y1=\"364\" x2=\"700\" y2=\"364\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"380\" y1=\"40\" x2=\"380\" y2=\"340\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-dasharray=\"14 10\"/>\n<line x1=\"140\" y1=\"100\" x2=\"380\" y2=\"340\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"262,206 290,250 246,236\" fill=\"#E0A21A\"/>\n<line x1=\"380\" y1=\"340\" x2=\"620\" y2=\"100\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"514,206 530,162 486,178\" fill=\"#E0A21A\"/>\n<path d=\"M 380 250 A 90 90 0 0 0 316 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<path d=\"M 380 250 A 90 90 0 0 1 444 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">虛線是垂直鏡面的「法線」，兩個橘色角度一樣大。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">光在同一種物質裡<b>走直線</b>，所以被擋住就會有影子。</p>\n<p style=\"font-size:36px;line-height:1.5\">光打到光滑的表面會<b>反彈</b>，就像球打到牆壁彈回來。</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4;color:#B4521F\">入射角 = 反射角</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：照鏡子、平靜湖面的倒影、腳踏車的反光片。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 10</p>\n\n</section>", "note": "用手電筒照鏡子示範：改變照射角度，反射出去的角度也跟著改變，而且兩邊永遠一樣大。角度是從法線開始量，不是從鏡面量。"}, {"id": "refract", "html": "<section id=\"refract\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">光 Light</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">光的折射 refraction</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"一杯水裡插著一根筷子，筷子在水面的地方看起來像折斷了一樣\" width=\"640\" height=\"440\" viewBox=\"0 0 640 440\">\n<path d=\"M150 60 L180 420 L460 420 L490 60\" fill=\"none\" stroke=\"#4F5F64\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n<path d=\"M163 200 L180 420 L460 420 L477 200 Z\" fill=\"#9CC0EA\" opacity=\"0.7\"/>\n<line x1=\"163\" y1=\"200\" x2=\"477\" y2=\"200\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<line x1=\"230\" y1=\"20\" x2=\"330\" y2=\"200\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"452\" y2=\"318\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"430\" y2=\"380\" stroke=\"#8A5A2B\" stroke-width=\"6\" stroke-dasharray=\"10 10\" opacity=\"0.5\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">實線是看到的筷子；淡淡的虛線是筷子真正的位置。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">光從水進入空氣時<b>速度改變</b>，前進方向就會<b style=\"color:#B4521F\">偏折</b>，這叫做折射。</p>\n<p style=\"font-size:36px;line-height:1.5\">所以筷子在水面的地方看起來<b>像折斷了</b>，其實它還是直的。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">其他例子：游泳池看起來比實際淺；眼鏡和放大鏡都是利用折射讓光轉彎。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 11</p>\n\n</section>", "note": "課堂上直接拿透明杯裝水、插一根筷子，從側面看。提醒學生：反射是光「彈回來」，折射是光「穿過去但轉彎」。透鏡就是利用折射。"}, {"id": "lens", "html": "<section id=\"lens\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">凸透鏡 convex lens</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">凸透鏡會把光聚在一點</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"三道平行光從左邊射向凸透鏡，穿過後聚在右邊的焦點；焦點到透鏡中心的距離是焦距\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"170\" x2=\"1460\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<line x1=\"60\" y1=\"70\" x2=\"700\" y2=\"70\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"170\" x2=\"700\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"270\" x2=\"700\" y2=\"270\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"70\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"270\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"170\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<ellipse cx=\"700\" cy=\"170\" rx=\"36\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"1100\" cy=\"170\" r=\"16\" fill=\"#B4521F\"/>\n<line x1=\"700\" y1=\"320\" x2=\"1100\" y2=\"320\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"700\" y1=\"304\" x2=\"700\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"1100\" y1=\"304\" x2=\"1100\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">平行光穿過凸透鏡後聚在一點（橘色點），下方的橘色線是焦距。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b>凸透鏡</b>：中間厚、邊緣薄，像放大鏡。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">焦點 F</b>：平行光聚集的那一點。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">焦距 f</b>：透鏡中心到焦點的距離。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 12</p>\n\n</section>", "note": "可以在太陽下用放大鏡把光聚成一個小亮點，那就是焦點（注意不要對著眼睛或易燃物）。提醒學生：這裡的 f 是焦距，和前面波速公式裡的頻率 f 是不同的東西，只是剛好用同一個字母。"}, {"id": "images", "html": "<section id=\"images\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">凸透鏡成像規律</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">物體放多遠，就成什麼樣的像</h2>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">物距（物體到透鏡）</th><th style=\"width:38%;text-align:left\">像的樣子</th><th style=\"width:28%;text-align:left\">應用</th></tr>\n<tr><td>大於 2 倍焦距</td><td>倒立、縮小、實像</td><td>相機、眼睛</td></tr>\n<tr><td>等於 2 倍焦距</td><td>倒立、等大、實像</td><td>—</td></tr>\n<tr style=\"background:#F7E6DC\"><td>在焦距和 2 倍焦距之間</td><td>倒立、放大、實像</td><td>投影機</td></tr>\n<tr><td>等於焦距</td><td>不成像</td><td>—</td></tr>\n<tr style=\"background:#E1ECFA\"><td>小於焦距</td><td>正立、放大、虛像</td><td>放大鏡</td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\"><b style=\"color:#18262B\">實像</b>：可以投影在屏幕上。<b style=\"color:#18262B\">虛像</b>：只能透過透鏡看到，投影不出來。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 13</p>\n\n</section>", "note": "記憶口訣：物體越靠近焦點，像越大；一進入焦距以內，就變成正立的放大虛像。可以拿放大鏡從遠到近看一個字，親眼看到像從倒立縮小、倒立放大，到正立放大的變化。"}, {"id": "rays", "html": "<section id=\"rays\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">畫圖找出像</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">兩條光線，就能找到像在哪裡</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"成像作圖：物體在透鏡左邊，一條光線平行主軸射到透鏡後穿過右邊焦點，另一條穿過透鏡中心直線前進，兩線在右邊交會，形成倒立放大的像\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"200\" x2=\"1460\" y2=\"200\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<ellipse cx=\"700\" cy=\"200\" rx=\"30\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"500\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<circle cx=\"900\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<line x1=\"400\" y1=\"200\" x2=\"400\" y2=\"164\" stroke=\"#18262B\" stroke-width=\"10\"/>\n<polygon points=\"384,168 400,140 416,168\" fill=\"#18262B\"/>\n<line x1=\"400\" y1=\"140\" x2=\"700\" y2=\"140\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"700\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"400\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#2463B8\" stroke-width=\"7\"/>\n<line x1=\"1300\" y1=\"200\" x2=\"1300\" y2=\"296\" stroke=\"#B4521F\" stroke-width=\"10\"/>\n<polygon points=\"1284,292 1300,322 1316,292\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">橘點是焦點。焦距 10 cm、物體放在 15 cm 處 → 像在另一側 30 cm，倒立、放大 2 倍的實像。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #E0A21A;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:700\">黃色光線</h3>\n<p style=\"font-size:28px;line-height:1.5\">平行主軸射向透鏡 → 穿過後<b>經過另一側的焦點</b>。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #2463B8;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:700\">藍色光線</h3>\n<p style=\"font-size:28px;line-height:1.5\">經過透鏡中心 → <b>直直前進，不會偏折</b>。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 14</p>\n\n</section>", "note": "兩條線的交點就是像的位置。作圖題只要記住這兩條光線就夠了。這一例的物體在焦距和 2 倍焦距之間，所以對照上一張表，是倒立放大的實像，就是投影機的原理。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">凸透鏡一定會把東西放大嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.1\">不一定。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:36px;line-height:1.5\">物體在<b>焦距以內</b>，才會看到正立、放大的虛像，這就是放大鏡平常的用法。</p>\n<p style=\"font-size:36px;line-height:1.5\">拿放大鏡看<b>遠方的窗戶</b>，看到的是<b>倒立、縮小</b>的像，跟相機拍照的原理一樣。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">波動、聲音與光 · 15</p>\n\n</section>", "note": "現場示範最有說服力：請學生把放大鏡伸直手臂，看教室另一頭或窗外，會看到上下顛倒的小影像。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗 Quick check</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:36px;line-height:1.5\">兩位太空人在太空艙外，不用無線電大聲喊，聽得到彼此嗎？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:36px;line-height:1.5\">空氣中聲速 340 m/s，680 Hz 的聲音波長是多少？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:36px;line-height:1.5\">焦距 10 cm 的凸透鏡，物體放在 30 cm 處，會成什麼樣的像？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 16</p>\n\n</section>", "note": "給學生 1 分鐘作答。Q2 提醒他們用 λ = v ÷ f；Q3 先算 30 cm 是焦距的幾倍，再查成像規律表。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:700\">聽不到</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">太空是真空，沒有介質，聲音傳不出去。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:700\">0.5 公尺</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">λ = v ÷ f = 340 ÷ 680 = 0.5 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:700\">倒立、縮小的實像</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">30 cm 大於 2 倍焦距（20 cm），就像相機。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.4\">波傳的是能量，不是東西。<br><span style=\"color:#E58A55\">聲音需要介質，光不用；凸透鏡成像看物距。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">波動、聲音與光 · 17</p>\n\n</section>", "note": "回到開場的謎題：聲波波長和門縫、轉角差不多大，所以能繞過去；光的波長極短，幾乎只走直線，被牆擋住就看不到人。"}]}, "waves-en": {"title": "Waves, Sound & Light", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS FROM ZERO · LESSON 3</p>\n<h1 style=\"font-size:104px;font-weight:900;line-height:1.05;color:#F3F5F2\">Waves,<br>Sound &amp; Light</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">How do sound and light travel to you?</p>\n</div>\n<svg aria-label=\"Three waves: a long orange wave on top, a shorter blue wave in the middle, and yellow light rays passing through a lens to meet at a point\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M20 110 C 110 20, 200 20, 290 110 S 470 200, 560 110 S 650 20, 700 70\" fill=\"none\" stroke=\"#E58A55\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M20 250 C 60 200, 100 200, 140 250 S 220 300, 260 250 S 340 200, 380 250 S 460 300, 500 250 S 580 200, 620 250 S 680 290, 700 270\" fill=\"none\" stroke=\"#7FB0F2\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"20\" y1=\"350\" x2=\"330\" y2=\"350\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"400\" x2=\"330\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"450\" x2=\"330\" y2=\"450\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"350\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"450\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"400\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<ellipse cx=\"330\" cy=\"400\" rx=\"22\" ry=\"70\" fill=\"#7FB0F2\" opacity=\"0.55\" stroke=\"#F3F5F2\" stroke-width=\"4\"/>\n<circle cx=\"560\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "Lesson 3 starts with waves. Sound and light are both waves, just with different personalities. We meet waves first, then look at sound and light, and finish by predicting what image a convex lens makes."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why can you hear the next room, but not see into it?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Sound</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Slips under doors and bends around corners, so <b style=\"color:#18262B\">you hear it through a wall</b>.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Light</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Travels almost only in straight lines, so <b style=\"color:#18262B\">a wall blocks it</b> and you can’t see who’s there.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Sound and light are both <b style=\"color:#B4521F\">waves</b>, with different personalities. Let’s meet them.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 2</p>\n\n</section>", "note": "Let students guess. The answer has to do with wavelength: sound waves are tens of centimeters to a few meters long, about the size of doorways and corners, so they bend around them easily. Light’s wavelength is tiny, so it travels almost in straight lines. Come back to this after teaching wavelength."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Read a wave</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Name wavelength and frequency, and use v = fλ.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain sound</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Tell its three properties apart and why it needs a medium.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Predict images</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say what image a convex lens makes at each distance.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 3</p>\n\n</section>", "note": "The three goals match the three parts: waves, sound, and light with lenses. We end with a myth and a three-question quiz."}, {"id": "wave", "html": "<section id=\"wave\" data-section=\"What a wave is: wavelength, frequency and wave speed\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WHAT IS A WAVE?</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A wave carries energy, not stuff</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A stadium wave: a row of people, a few in the middle standing with arms up, the rest seated; an arrow shows the wave moving right while everyone stays in their seat\" width=\"1600\" height=\"300\" viewBox=\"0 0 1600 300\">\n<line x1=\"40\" y1=\"270\" x2=\"1560\" y2=\"270\" stroke=\"#9AAAA6\" stroke-width=\"6\"/>\n<g fill=\"#4F5F64\">\n<circle cx=\"100\" cy=\"200\" r=\"22\"/><rect x=\"80\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"220\" cy=\"200\" r=\"22\"/><rect x=\"200\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"340\" cy=\"200\" r=\"22\"/><rect x=\"320\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"460\" cy=\"190\" r=\"22\"/><rect x=\"440\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n</g>\n<g fill=\"#B4521F\">\n<circle cx=\"580\" cy=\"150\" r=\"22\"/><rect x=\"560\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"580\" y1=\"128\" x2=\"580\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"700\" cy=\"110\" r=\"22\"/><rect x=\"680\" y=\"132\" width=\"40\" height=\"138\" rx=\"10\"/><line x1=\"700\" y1=\"88\" x2=\"700\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"820\" cy=\"150\" r=\"22\"/><rect x=\"800\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"820\" y1=\"128\" x2=\"820\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n</g>\n<g fill=\"#4F5F64\">\n<circle cx=\"940\" cy=\"190\" r=\"22\"/><rect x=\"920\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n<circle cx=\"1060\" cy=\"200\" r=\"22\"/><rect x=\"1040\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1180\" cy=\"200\" r=\"22\"/><rect x=\"1160\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1300\" cy=\"200\" r=\"22\"/><rect x=\"1280\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n</g>\n<line x1=\"1380\" y1=\"120\" x2=\"1520\" y2=\"120\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"1520,96 1560,120 1520,144\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">A stadium wave: the “stand up” moves right, but everyone stays in their own seat.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">A wave is a <b>vibration</b> passed along, one neighbor to the next. What travels is <b style=\"color:#B4521F\">energy</b>; the material stays put.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">Drop a stone in a pond: ripples spread out, but a leaf on the water just <b>bobs up and down</b>.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 4</p>\n\n</section>", "note": "Have the class do a stadium wave. Each person just stands and sits, never leaving their seat, yet the “stand up” travels across the room. That is a wave: it carries energy, not stuff."}, {"id": "parts", "html": "<section id=\"parts\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Three things to know about a wave</h2>\n<svg aria-label=\"A wavy line: an orange bracket marks the distance between two crests as the wavelength, and a blue line marks the height from the middle line to a crest as the amplitude\" width=\"1664\" height=\"250\" viewBox=\"0 0 1664 250\">\n<line x1=\"0\" y1=\"170\" x2=\"1560\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<path d=\"M0 170 C 80 50, 170 50, 250 170 S 420 290, 500 170 S 670 50, 750 170 S 920 290, 1000 170 S 1170 50, 1250 170 S 1420 290, 1500 170\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"125\" y1=\"30\" x2=\"625\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"125\" y1=\"12\" x2=\"125\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"625\" y1=\"12\" x2=\"625\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"1125\" y1=\"82\" x2=\"1125\" y2=\"170\" stroke=\"#2463B8\" stroke-width=\"10\"/>\n<polygon points=\"1112,96 1125,74 1138,96\" fill=\"#2463B8\"/>\n</svg>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Wavelength <span style=\"color:#B4521F\">λ</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">Unit: meters (m)</p>\n<p style=\"font-size:30px;line-height:1.5\">The distance from one <b>crest</b> to the next (orange bracket).</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Amplitude</h3>\n<p style=\"font-size:24px;color:#4F5F64\">How tall the wave is</p>\n<p style=\"font-size:30px;line-height:1.5\">The height of a crest above the middle (blue line). Bigger = more energy.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Frequency <span style=\"color:#4F5F64\">f</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">Unit: hertz (Hz)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>Vibrations per second.</b> 100 Hz means 100 vibrations every second.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 5</p>\n\n</section>", "note": "Wavelength and amplitude show up in the picture; frequency is about time: how many waves pass each second. Use a jump rope: swing it faster for higher frequency, swing it harder (higher) for bigger amplitude."}, {"id": "speed", "html": "<section id=\"speed\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">WAVE SPEED</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">v</p>\n<p style=\"font-size:32px;color:#BFCDC9\">speed (m/s)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">f</p>\n<p style=\"font-size:32px;color:#BFCDC9\">frequency (Hz)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">λ</p>\n<p style=\"font-size:32px;color:#BFCDC9\">wavelength (m)</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Example: sound in air travels about 340 m/s. A 170 Hz sound has<br>λ = v ÷ f = 340 ÷ 170 = <span style=\"color:#E58A55\">2 meters</span></p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">For one kind of wave in one material, the speed stays the same: higher frequency means shorter wavelength.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Waves, Sound &amp; Light · 6</p>\n\n</section>", "note": "One way to see it: the wave vibrates f times per second and moves one wavelength each time, so it covers f × λ every second. Like Ohm’s law, know two and you can find the third. 340 m/s is roughly the speed of sound in air at about 15 °C."}, {"id": "kinds", "html": "<section id=\"kinds\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TWO SHAPES OF WAVES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Transverse and longitudinal</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Transverse</h3>\n<svg aria-label=\"Transverse wave: a rope rises and falls; a blue arrow shows the wave moving right and an orange arrow shows the rope moving up and down\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<path d=\"M20 100 C 70 20, 120 20, 170 100 S 270 180, 320 100 S 420 20, 470 100 S 570 180, 620 100\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"95\" y1=\"70\" x2=\"95\" y2=\"150\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"84,74 95,54 106,74\" fill=\"#B4521F\"/>\n<polygon points=\"84,146 95,166 106,146\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">Like shaking a rope: it moves <b style=\"color:#B4521F\">up and down</b> while the wave travels <b style=\"color:#2463B8\">sideways</b>.</p>\n<p style=\"font-size:28px;color:#4F5F64\">Examples: rope waves, <b style=\"color:#18262B\">light</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Longitudinal</h3>\n<svg aria-label=\"Longitudinal wave: vertical lines bunched together in some places and spread apart in others, like a pushed spring; a blue arrow shows the wave moving right and an orange double arrow shows back-and-forth motion\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<g stroke=\"#18262B\" stroke-width=\"6\">\n<line x1=\"30\" y1=\"50\" x2=\"30\" y2=\"150\"/><line x1=\"48\" y1=\"50\" x2=\"48\" y2=\"150\"/><line x1=\"64\" y1=\"50\" x2=\"64\" y2=\"150\"/><line x1=\"78\" y1=\"50\" x2=\"78\" y2=\"150\"/>\n<line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"150\"/><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"150\"/><line x1=\"220\" y1=\"50\" x2=\"220\" y2=\"150\"/>\n<line x1=\"256\" y1=\"50\" x2=\"256\" y2=\"150\"/><line x1=\"274\" y1=\"50\" x2=\"274\" y2=\"150\"/><line x1=\"290\" y1=\"50\" x2=\"290\" y2=\"150\"/><line x1=\"304\" y1=\"50\" x2=\"304\" y2=\"150\"/>\n<line x1=\"346\" y1=\"50\" x2=\"346\" y2=\"150\"/><line x1=\"396\" y1=\"50\" x2=\"396\" y2=\"150\"/><line x1=\"446\" y1=\"50\" x2=\"446\" y2=\"150\"/>\n<line x1=\"482\" y1=\"50\" x2=\"482\" y2=\"150\"/><line x1=\"500\" y1=\"50\" x2=\"500\" y2=\"150\"/><line x1=\"516\" y1=\"50\" x2=\"516\" y2=\"150\"/><line x1=\"530\" y1=\"50\" x2=\"530\" y2=\"150\"/>\n<line x1=\"572\" y1=\"50\" x2=\"572\" y2=\"150\"/><line x1=\"620\" y1=\"50\" x2=\"620\" y2=\"150\"/>\n</g>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"150\" y1=\"180\" x2=\"250\" y2=\"180\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"152,169 132,180 152,191\" fill=\"#B4521F\"/>\n<polygon points=\"248,169 268,180 248,191\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">Like pushing a spring: it squeezes <b style=\"color:#B4521F\">back and forth</b> in the <b style=\"color:#2463B8\">same direction</b> the wave travels.</p>\n<p style=\"font-size:28px;color:#4F5F64\">Examples: spring waves, <b style=\"color:#18262B\">sound</b></p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 7</p>\n\n</section>", "note": "A Slinky shows both: wiggle it side to side for a transverse wave, push and pull it for a longitudinal wave. Sound is air being squeezed and stretched (longitudinal); light is transverse."}, {"id": "sound3", "html": "<section id=\"sound3\" data-section=\"Sound: its three properties and why it needs a medium\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">SOUND</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Three properties of sound</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:22%;text-align:left\">Property</th><th style=\"width:36%;text-align:left\">Set by</th><th style=\"width:42%;text-align:left\">Everyday example</th></tr>\n<tr><td><b>Loudness</b></td><td><span style=\"color:#2463B8\">Amplitude</span>: bigger is louder</td><td>Whispering vs. shouting</td></tr>\n<tr><td><b>Pitch</b></td><td><span style=\"color:#B4521F\">Frequency</span>: higher is shriller</td><td>A bird’s chirp (high) vs. a bass drum (low)</td></tr>\n<tr><td><b>Timbre</b></td><td>Wave shape: different for every instrument</td><td>Piano and violin playing the same note still sound different</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Human ears hear about <b>20–20,000 Hz</b>. Higher than that is ultrasound, which dogs and bats can hear.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 8</p>\n\n</section>", "note": "Connect to the last section: amplitude sets loudness, frequency sets pitch. A free tone-generator app lets students hear the pitch rise as you slide the frequency up."}, {"id": "medium", "html": "<section id=\"medium\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">SOUND NEEDS A MEDIUM</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Can you hear an explosion in space?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:56px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:96px;font-weight:900;line-height:1.05;color:#B4521F\">No.</p>\n<p style=\"font-size:32px;line-height:1.5\">Sound travels by particles in a medium <b>pushing their neighbors</b>. Space is a vacuum with no particles to push, so sound can’t travel.</p>\n<p style=\"font-size:32px;line-height:1.5\">Light doesn’t need a medium, which is how sunlight crosses space to reach Earth.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:52%;text-align:left\">Traveling through</th><th style=\"width:48%;text-align:right\">Speed (about)</th></tr>\n<tr><td>Sound in air</td><td style=\"text-align:right\">340 m/s</td></tr>\n<tr><td>Sound in water</td><td style=\"text-align:right\">1,500 m/s</td></tr>\n<tr><td>Sound in steel</td><td style=\"text-align:right\">5,000 m/s</td></tr>\n<tr style=\"background:#E1ECFA\"><td><b>Light</b></td><td style=\"text-align:right\"><b>300,000,000 m/s</b></td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Light is far faster, which is why you <b style=\"color:#18262B\">see lightning before you hear thunder</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 9</p>\n\n</section>", "note": "The “boom” in space movies is a sound effect; real space is silent. Extension: count the seconds between a lightning flash and the thunder, multiply by 340, and you get roughly how many meters away it struck. All speeds are approximate and change with temperature and material."}, {"id": "reflect", "html": "<section id=\"reflect\" data-section=\"Light: reflection, refraction and convex lenses\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LIGHT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Reflection: light bounces</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Reflection: a ray of light hits a mirror at an angle and bounces off; a dashed normal line stands between them, and the two angles are equal\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<rect x=\"60\" y=\"340\" width=\"640\" height=\"24\" fill=\"#9CC0EA\" stroke=\"#2463B8\" stroke-width=\"4\"/>\n<line x1=\"60\" y1=\"364\" x2=\"700\" y2=\"364\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"380\" y1=\"40\" x2=\"380\" y2=\"340\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-dasharray=\"14 10\"/>\n<line x1=\"140\" y1=\"100\" x2=\"380\" y2=\"340\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"262,206 290,250 246,236\" fill=\"#E0A21A\"/>\n<line x1=\"380\" y1=\"340\" x2=\"620\" y2=\"100\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"514,206 530,162 486,178\" fill=\"#E0A21A\"/>\n<path d=\"M 380 250 A 90 90 0 0 0 316 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<path d=\"M 380 250 A 90 90 0 0 1 444 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The dashed “normal” line is at right angles to the mirror. The two orange angles match.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">Light travels in <b>straight lines</b>, which is why blocked light makes a shadow.</p>\n<p style=\"font-size:34px;line-height:1.5\">When light hits a smooth surface it <b>bounces off</b>, like a ball off a wall.</p>\n<p style=\"font-size:44px;font-weight:800;line-height:1.35;color:#B4521F\">Angle in = angle out</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Examples: mirrors, reflections on a calm lake, bike reflectors.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 10</p>\n\n</section>", "note": "Shine a flashlight at a mirror and change the angle: the reflected beam moves too, and the two angles always match. Angles are measured from the normal line, not from the mirror surface."}, {"id": "refract", "html": "<section id=\"refract\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LIGHT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Refraction: light bends</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A chopstick standing in a glass of water looks bent at the water’s surface\" width=\"640\" height=\"440\" viewBox=\"0 0 640 440\">\n<path d=\"M150 60 L180 420 L460 420 L490 60\" fill=\"none\" stroke=\"#4F5F64\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n<path d=\"M163 200 L180 420 L460 420 L477 200 Z\" fill=\"#9CC0EA\" opacity=\"0.7\"/>\n<line x1=\"163\" y1=\"200\" x2=\"477\" y2=\"200\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<line x1=\"230\" y1=\"20\" x2=\"330\" y2=\"200\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"452\" y2=\"318\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"430\" y2=\"380\" stroke=\"#8A5A2B\" stroke-width=\"6\" stroke-dasharray=\"10 10\" opacity=\"0.5\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Solid: what you see. Faint dashes: where the chopstick really is.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">When light passes from water into air, it <b>changes speed</b>, so its direction <b style=\"color:#B4521F\">bends</b>. That’s refraction.</p>\n<p style=\"font-size:34px;line-height:1.5\">That’s why the chopstick <b>looks broken</b> at the surface, even though it’s perfectly straight.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">More examples: a pool looks shallower than it is; glasses and magnifiers use refraction to bend light.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 11</p>\n\n</section>", "note": "Put a pencil or chopstick in a clear glass of water and look from the side. Remind students: reflection is light bouncing back; refraction is light going through but changing direction. Lenses work by refraction."}, {"id": "lens", "html": "<section id=\"lens\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">CONVEX LENS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A convex lens brings light to a point</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Three parallel light rays enter a convex lens from the left and meet at the focal point on the right; the distance from the lens center to that point is the focal length\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"170\" x2=\"1460\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<line x1=\"60\" y1=\"70\" x2=\"700\" y2=\"70\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"170\" x2=\"700\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"270\" x2=\"700\" y2=\"270\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"70\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"270\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"170\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<ellipse cx=\"700\" cy=\"170\" rx=\"36\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"1100\" cy=\"170\" r=\"16\" fill=\"#B4521F\"/>\n<line x1=\"700\" y1=\"320\" x2=\"1100\" y2=\"320\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"700\" y1=\"304\" x2=\"700\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"1100\" y1=\"304\" x2=\"1100\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Parallel rays pass through and meet at one point (orange dot). The orange line below is the focal length.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b>Convex lens:</b> thick in the middle, thin at the edges, like a magnifier.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">Focal point F:</b> where parallel rays meet.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">Focal length f:</b> from the lens center to the focal point.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 12</p>\n\n</section>", "note": "Outdoors, a magnifier can focus sunlight into a small bright spot: that’s the focal point (never aim it at eyes or anything flammable). Remind students that this f means focal length; it is not the frequency f from the wave-speed formula, just the same letter."}, {"id": "images", "html": "<section id=\"images\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">CONVEX LENS IMAGES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Where the object is decides the image</h2>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">Object distance</th><th style=\"width:38%;text-align:left\">Image</th><th style=\"width:26%;text-align:left\">Used in</th></tr>\n<tr><td>More than 2f</td><td>Upside down, smaller, real</td><td>Camera, eye</td></tr>\n<tr><td>Exactly 2f</td><td>Upside down, same size, real</td><td>—</td></tr>\n<tr style=\"background:#F7E6DC\"><td>Between f and 2f</td><td>Upside down, larger, real</td><td>Projector</td></tr>\n<tr><td>Exactly f</td><td>No image</td><td>—</td></tr>\n<tr style=\"background:#E1ECFA\"><td>Less than f</td><td>Upright, larger, virtual</td><td>Magnifier</td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\"><b style=\"color:#18262B\">Real image:</b> can be projected on a screen. <b style=\"color:#18262B\">Virtual image:</b> seen only by looking through the lens.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 13</p>\n\n</section>", "note": "Memory trick: the closer the object gets to the focal point, the bigger the image; once it is inside the focal length, the image flips to upright and virtual. Look at a word through a magnifier from far to near to see the image go from small and upside down, to large and upside down, to large and upright."}, {"id": "rays", "html": "<section id=\"rays\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">DRAW IT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Two rays find the image</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Ray diagram: an object stands left of the lens; one ray runs parallel to the axis, bends through the far focal point; another passes straight through the lens center; they cross on the right, forming a larger upside-down image\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"200\" x2=\"1460\" y2=\"200\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<ellipse cx=\"700\" cy=\"200\" rx=\"30\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"500\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<circle cx=\"900\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<line x1=\"400\" y1=\"200\" x2=\"400\" y2=\"164\" stroke=\"#18262B\" stroke-width=\"10\"/>\n<polygon points=\"384,168 400,140 416,168\" fill=\"#18262B\"/>\n<line x1=\"400\" y1=\"140\" x2=\"700\" y2=\"140\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"700\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"400\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#2463B8\" stroke-width=\"7\"/>\n<line x1=\"1300\" y1=\"200\" x2=\"1300\" y2=\"296\" stroke=\"#B4521F\" stroke-width=\"10\"/>\n<polygon points=\"1284,292 1300,322 1316,292\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Orange dots are focal points. f = 10 cm, object at 15 cm → image at 30 cm on the other side, upside down and 2× larger.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #E0A21A;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:800\">Yellow ray</h3>\n<p style=\"font-size:28px;line-height:1.5\">Comes in parallel to the axis → bends <b>through the far focal point</b>.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #2463B8;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:800\">Blue ray</h3>\n<p style=\"font-size:28px;line-height:1.5\">Goes through the lens center → <b>keeps going straight</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 14</p>\n\n</section>", "note": "Where the two rays cross is where the image forms. These two rays are all you need for any ray-diagram question. Here the object sits between f and 2f, so by the table on the previous slide the image is real, upside down and larger: how a projector works."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does a convex lens always magnify?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">Not always.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">Only when the object is <b>inside the focal length</b> do you see an upright, larger, virtual image. That’s the usual magnifier view.</p>\n<p style=\"font-size:34px;line-height:1.5\">Look at a <b>faraway window</b> through a magnifier and you see a <b>small, upside-down</b> image, the same way a camera works.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Waves, Sound &amp; Light · 15</p>\n\n</section>", "note": "A live demo convinces best: have students hold a magnifier at arm’s length and look across the room or out a window. They’ll see a small, upside-down picture."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">Two astronauts on a spacewalk shout without radios. Can they hear each other?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Sound travels at 340 m/s in air. What is the wavelength of a 680 Hz sound?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">A convex lens has f = 10 cm. An object sits 30 cm away. What image forms?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 16</p>\n\n</section>", "note": "Give students one minute. For Q2, remind them λ = v ÷ f. For Q3, ask how many focal lengths 30 cm is, then check the table."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">No</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Space is a vacuum with no medium, so sound can’t travel.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">0.5 meters</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">λ = 340 ÷ 680 = 0.5 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Smaller, upside down, real</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">30 cm is more than 2f (20 cm), like a camera.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Waves carry energy, not stuff.<br><span style=\"color:#E58A55\">Sound needs a medium, light doesn’t; lens images depend on distance.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Waves, Sound &amp; Light · 17</p>\n\n</section>", "note": "Back to the opening puzzle: sound waves are about as long as doorways and corners, so they bend around them; light’s wavelength is tiny, so it travels in nearly straight lines and a wall blocks it."}]}, "chem-reactions-en": {"title": "L1 Chemical Reactions & Conservation of Mass", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#1E2A3A;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;color:#F2A65A;letter-spacing:2px\">GRADE 8 SCIENCE · LESSON 1 · 15 MIN</p>\n<h1 style=\"font-size:96px;font-weight:700;line-height:1.1;color:#F7F5EF\">Chemical Reactions &amp; Conservation of Mass</h1>\n<p style=\"font-size:44px;color:#BFD0DC\">Does mass change when substances react?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8FA3B5\">Mini Lesson · Hook → Concept → Misconceptions → Practice → Exit Ticket</p>\n\n</section>", "note": "Opening (30 seconds): Today we answer one question. When a chemical reaction happens, does the total mass change?"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Goals &amp; Key Terms</h2>\n<div style=\"display:flex;gap:64px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px\">\n<h3 style=\"font-size:32px;font-weight:700;color:#C2611F\">By the end of class, you can…</h3>\n<ul style=\"font-size:32px;line-height:1.5;color:#3A4656\">\n<li>Explain why the total number of atoms stays the same</li>\n<li>Balance simple chemical equations</li>\n<li>Use moles in a one-step calculation</li>\n</ul>\n<p style=\"font-size:24px;color:#5A6676;background:#FBE8D6;padding:20px 28px;border-radius:12px\">Materials: baking soda, vinegar, plastic bottle, balloon, digital scale</p>\n</div>\n<table style=\"flex:1;width:820px;font-size:28px;color:#1E2A3A\">\n<tr><th style=\"width:42%\">Term</th><th style=\"width:58%\">Meaning</th></tr>\n<tr><td>reactant</td><td>a substance you start with</td></tr>\n<tr><td>product</td><td>a new substance that forms</td></tr>\n<tr><td>conservation of mass</td><td>total mass stays the same</td></tr>\n<tr><td>coefficient</td><td>number in front of a formula</td></tr>\n<tr><td>subscript</td><td>small number inside a formula</td></tr>\n<tr><td>molecular mass</td><td>sum of the atomic masses</td></tr>\n<tr><td>mole</td><td>6 × 10²³ particles</td></tr>\n</table>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L1 · Goals · Opening</p>\n\n</section>", "note": "Read each term aloud once. Students should use these terms on the exit ticket."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#EAF1EE;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Predict</h2>\n<div style=\"display:flex;gap:40px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #D3DED9\">\n<p style=\"font-size:28px;font-weight:700;color:#C2611F\">GROUP A · OPEN</p>\n<p style=\"font-size:32px;line-height:1.5;color:#3A4656\">Add baking soda to vinegar in an open beaker.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #D3DED9\">\n<p style=\"font-size:28px;font-weight:700;color:#C2611F\">GROUP B · CLOSED</p>\n<p style=\"font-size:32px;line-height:1.5;color:#3A4656\">Put baking soda in a balloon, fit it over a bottle of vinegar, then tip it in.</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.3\">After the reaction, will the mass of each group change?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L1 · Hook · 0–2 min</p>\n\n</section>", "note": "Have students raise hands to predict, then weigh both setups. Result: Group A gets lighter, Group B stays the same. Don’t explain yet; save it for the next slide."}, {"id": "concept", "html": "<section id=\"concept\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Core Concept</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:28px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #E07A2E\">\n<h3 style=\"font-size:32px;font-weight:700\">1 Atoms rearrange</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">Atoms are not created or destroyed, so total mass stays the same.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #E07A2E\">\n<h3 style=\"font-size:32px;font-weight:700\">2 Why Group A got lighter</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">CO₂ gas escaped into the air. The mass did not disappear.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #E07A2E\">\n<h3 style=\"font-size:32px;font-weight:700\">3 Change coefficients, not subscripts</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">A new subscript makes a different substance: H₂O → H₂O₂</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #E07A2E\">\n<h3 style=\"font-size:32px;font-weight:700\">4 The mole</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">1 mol = 6 × 10²³ particles<br>mass (g) = moles × molecular mass</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L1 · Core Concept · 2–7 min</p>\n\n</section>", "note": "Link back to the hook: in Group B the balloon trapped the CO₂, so the scale showed no change."}, {"id": "myth", "html": "<section id=\"myth\" data-transition=\"fade\" style=\"background:#EAF1EE;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">True or False?</h2>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #E07A2E\">1　“A candle gets lighter as it burns, so mass is not conserved.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #E07A2E\">2　“To balance H₂ + O₂ → H₂O, just change the product to H₂O₂.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #E07A2E\">3　“The ratio of coefficients is the ratio of masses.”</p>\n</div>\n<p style=\"font-size:28px;color:#5A6676\">Explain what’s wrong with each statement.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L1 · Misconceptions · 7–11 min</p>\n\n</section>", "note": "All three are false. 1: The CO₂ and H₂O produced escape into the air. 2: Changing a subscript makes a different substance; the correct equation is 2H₂ + O₂ → 2H₂O. 3: Coefficients give the ratio of moles, not masses."}, {"id": "practice", "html": "<section id=\"practice\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Pair Practice</h2>\n<div style=\"display:flex;gap:40px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#C2611F\">Q1</p>\n<p style=\"font-size:44px;font-weight:700\">CH₄ + O₂ → CO₂ + H₂O</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">Balance the equation.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#C2611F\">Q2</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">How many grams of O₂ are needed to burn 16 g of CH₄ completely?</p>\n<p style=\"font-size:24px;color:#5A6676\">C = 12 · H = 1 · O = 16</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L1 · Practice · 11–14 min</p>\n\n</section>", "note": "Q1: CH₄ + 2O₂ → CO₂ + 2H₂O. Q2: 16 g CH₄ = 1 mol, which needs 2 mol O₂ = 2 × 32 = 64 g."}, {"id": "exit", "html": "<section id=\"exit\" data-transition=\"fade\" style=\"background:#E07A2E;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:40px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:2px\">EXIT TICKET · WORK ON YOUR OWN</p>\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.2\">In one sentence, explain why Group B’s mass did not change.</h2>\n<p style=\"font-size:32px;color:#3A2A1A\">Use the words “atoms” and “conservation of mass.”</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#3A2A1A\">L1 · Exit Ticket · 14–15 min</p>\n\n</section>", "note": "Sample answer: In the closed container the CO₂ could not escape, and the total number of atoms stayed the same, so the mass did not change."}]}, "chem-acids-en": {"title": "L2 Acids, Bases & Salts", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#1E2A3A;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;color:#C3A6EA;letter-spacing:2px\">GRADE 8 SCIENCE · LESSON 2 · 15 MIN</p>\n<h1 style=\"font-size:120px;font-weight:700;line-height:1.1;color:#F7F5EF\">Acids, Bases &amp; Salts</h1>\n<p style=\"font-size:44px;color:#BFD0DC\">What makes a solution acidic or basic?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8FA3B5\">Mini Lesson · Hook → Concept → Misconceptions → Practice → Exit Ticket</p>\n\n</section>", "note": "Opening (30 seconds): Vinegar, soda, soapy water, baking soda water. Which are acids and which are bases? Today one cup of red cabbage juice will tell us."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Goals &amp; Key Terms</h2>\n<div style=\"display:flex;gap:64px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px\">\n<h3 style=\"font-size:32px;font-weight:700;color:#6B3FA8\">By the end of class, you can…</h3>\n<ul style=\"font-size:32px;line-height:1.5;color:#3A4656\">\n<li>Identify acids and bases by H⁺ and OH⁻</li>\n<li>Explain what a change of 1 on the pH scale means</li>\n<li>Write the products of a neutralization reaction</li>\n</ul>\n<p style=\"font-size:24px;color:#5A6676;background:#EEE6F7;padding:20px 28px;border-radius:12px\">Materials: red cabbage juice, 4 clear cups, vinegar, soda, soapy water, baking soda water</p>\n</div>\n<table style=\"flex:1;width:820px;font-size:28px;color:#1E2A3A\">\n<tr><th style=\"width:42%\">Term</th><th style=\"width:58%\">Meaning</th></tr>\n<tr><td>electrolyte</td><td>splits into ions in water</td></tr>\n<tr><td>acid</td><td>releases H⁺ in water</td></tr>\n<tr><td>base</td><td>releases OH⁻ in water</td></tr>\n<tr><td>pH</td><td>scale of acidity, 0–14</td></tr>\n<tr><td>indicator</td><td>changes color with pH</td></tr>\n<tr><td>neutralization</td><td>acid + base → salt + water</td></tr>\n<tr><td>salt</td><td>ionic product of neutralization</td></tr>\n</table>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L2 · Goals · Opening</p>\n\n</section>", "note": "Read each term aloud once. Phenolphthalein is introduced in the practice question."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#EFEAF4;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Predict</h2>\n<p style=\"font-size:32px;color:#3A4656\">Add each liquid to a cup of red cabbage juice:</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:28px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;background:#FBFBF8;padding:48px 24px;border-radius:20px;border:2px solid #DCD2E8\">\n<p style=\"font-size:44px;font-weight:700\">Vinegar</p>\n</div>\n<div style=\"display:flex;flex-direction:column;align-items:center;background:#FBFBF8;padding:48px 24px;border-radius:20px;border:2px solid #DCD2E8\">\n<p style=\"font-size:44px;font-weight:700\">Soda</p>\n</div>\n<div style=\"display:flex;flex-direction:column;align-items:center;background:#FBFBF8;padding:48px 24px;border-radius:20px;border:2px solid #DCD2E8\">\n<p style=\"font-size:44px;font-weight:700;text-align:center\">Soapy water</p>\n</div>\n<div style=\"display:flex;flex-direction:column;align-items:center;background:#FBFBF8;padding:48px 24px;border-radius:20px;border:2px solid #DCD2E8\">\n<p style=\"font-size:44px;font-weight:700;text-align:center\">Baking soda</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.3\">Which cups will turn red?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L2 · Hook · 0–2 min</p>\n\n</section>", "note": "Result: vinegar and soda turn red-pink (acidic); soapy water and baking soda water turn green (basic). Let groups guess first, then reveal."}, {"id": "concept", "html": "<section id=\"concept\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Core Concept</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:28px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #7A4FB5\">\n<h3 style=\"font-size:32px;font-weight:700\">1 Electrolytes</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">They split into ions in water, so they conduct electricity. Acids, bases and salts are all electrolytes.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #7A4FB5\">\n<h3 style=\"font-size:32px;font-weight:700\">2 Acids and bases</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">Acids release H⁺ in water.<br>Bases release OH⁻ in water.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #7A4FB5\">\n<h3 style=\"font-size:32px;font-weight:700\">3 pH at 25°C</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">&lt; 7 acidic · = 7 neutral · &gt; 7 basic<br>Each step of 1 = 10 times the [H⁺]</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFBF8;padding:36px;border-radius:16px;border-top:6px solid #7A4FB5\">\n<h3 style=\"font-size:32px;font-weight:700\">4 Neutralization</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">acid + base → salt + water<br>At its core: H⁺ + OH⁻ → H₂O</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L2 · Core Concept · 2–7 min</p>\n\n</section>", "note": "Link back to the hook: red cabbage juice is a natural indicator; its color shows how much H⁺ or OH⁻ is present. Stress that pH is a log scale; the exit ticket tests it."}, {"id": "myth", "html": "<section id=\"myth\" data-transition=\"fade\" style=\"background:#EFEAF4;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">True or False?</h2>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #7A4FB5\">1　“pH 3 is only a little more acidic than pH 5.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #7A4FB5\">2　“Salt just means table salt.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #7A4FB5\">3　“Sugar water conducts electricity because sugar dissolves.”</p>\n</div>\n<p style=\"font-size:28px;color:#5A6676\">Explain what’s wrong with each statement.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L2 · Misconceptions · 7–11 min</p>\n\n</section>", "note": "All three are false. 1: The [H⁺] differs by 100 times. 2: “Salt” is the general name for ionic compounds formed by neutralization; NaCl is only one of them. 3: Dissolving is not the same as splitting into ions; sugar is a non-electrolyte and does not conduct."}, {"id": "practice", "html": "<section id=\"practice\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Pair Practice</h2>\n<div style=\"display:flex;gap:40px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#6B3FA8\">Q1</p>\n<p style=\"font-size:44px;font-weight:700\">HCl + NaOH → ?</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">Write the products.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#6B3FA8\">Q2</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">Add phenolphthalein to NaOH solution, then slowly add hydrochloric acid. How does the color change, and why?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L2 · Practice · 11–14 min</p>\n\n</section>", "note": "Q1: NaCl + H₂O. Q2: The solution starts pink; as the acid neutralizes the OH⁻, the solution is no longer basic and the phenolphthalein turns colorless."}, {"id": "exit", "html": "<section id=\"exit\" data-transition=\"fade\" style=\"background:#6B3FA8;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:40px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:2px;color:#E4D6F7\">EXIT TICKET · WORK ON YOUR OWN</p>\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.2\">How many times more H⁺ does a pH 2 solution have than a pH 4 solution?</h2>\n<p style=\"font-size:32px;color:#E4D6F7\">Show how you got your answer.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#E4D6F7\">L2 · Exit Ticket · 14–15 min</p>\n\n</section>", "note": "Answer: 100 times (a difference of 2 → 10²). Students who answer 2 or 20 times need a quick review of the log scale at the start of next class."}]}, "chem-redox-en": {"title": "L3 Oxidation & Reduction", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#1E2A3A;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;color:#7CC7D3;letter-spacing:2px\">GRADE 8 SCIENCE · LESSON 3 · 15 MIN</p>\n<h1 style=\"font-size:120px;font-weight:700;line-height:1.1;color:#F7F5EF\">Oxidation &amp; Reduction</h1>\n<p style=\"font-size:44px;color:#BFD0DC\">Who gains oxygen, and who loses it?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8FA3B5\">Mini Lesson · Hook → Concept → Misconceptions → Practice → Exit Ticket</p>\n\n</section>", "note": "Opening (30 seconds): Why does iron rust? And how does a steel plant get iron out of iron ore? Both are two sides of the same kind of reaction."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Goals &amp; Key Terms</h2>\n<div style=\"display:flex;gap:64px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px\">\n<h3 style=\"font-size:32px;font-weight:700;color:#17657A\">By the end of class, you can…</h3>\n<ul style=\"font-size:32px;line-height:1.5;color:#3A4656\">\n<li>Identify oxidation and reduction by gain or loss of oxygen</li>\n<li>Use the reactivity series to predict whether a reaction happens</li>\n</ul>\n<p style=\"font-size:24px;color:#5A6676;background:#E2F0F2;padding:20px 28px;border-radius:12px\">Materials: iron nail (sanded clean), copper(II) sulfate solution, test tube — or a demo video</p>\n</div>\n<table style=\"flex:1;width:820px;font-size:28px;color:#1E2A3A\">\n<tr><th style=\"width:42%\">Term</th><th style=\"width:58%\">Meaning</th></tr>\n<tr><td>oxidation</td><td>a substance gains oxygen</td></tr>\n<tr><td>reduction</td><td>a substance loses oxygen</td></tr>\n<tr><td>oxidizing agent</td><td>gives oxygen away</td></tr>\n<tr><td>reducing agent</td><td>takes oxygen</td></tr>\n<tr><td>reactivity</td><td>how easily a metal reacts</td></tr>\n<tr><td>rusting</td><td>iron slowly oxidizing</td></tr>\n<tr><td>smelting</td><td>getting metal from ore</td></tr>\n</table>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L3 · Goals · Opening</p>\n\n</section>", "note": "At this level we define oxidation and reduction only by gain or loss of oxygen; electron transfer comes in high school."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#E8F1F2;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Predict</h2>\n<div style=\"display:flex;gap:40px;align-items:center\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #CFE0E3\">\n<p style=\"font-size:28px;font-weight:700;color:#17657A\">PUT IN</p>\n<p style=\"font-size:44px;font-weight:700\">A clean iron nail</p>\n</div>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#1F7A8C;width:96px;height:48px\"></div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:16px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #CFE0E3\">\n<p style=\"font-size:28px;font-weight:700;color:#17657A\">SOLUTION</p>\n<p style=\"font-size:44px;font-weight:700\">Blue copper(II) sulfate</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.3\">After 2 minutes, what will happen to the nail and the solution?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L3 · Hook · 0–2 min</p>\n\n</section>", "note": "Result: red copper coats the nail and the blue color fades. Have students write a prediction; explain after the concept slide."}, {"id": "concept", "html": "<section id=\"concept\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:32px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Core Concept</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px\">\n<div style=\"display:flex;flex-direction:column;gap:10px;background:#FBFBF8;padding:32px;border-radius:16px;border-top:6px solid #1F7A8C\">\n<h3 style=\"font-size:32px;font-weight:700\">1 Gain or lose oxygen</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">Gain oxygen = oxidation<br>Lose oxygen = reduction</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:10px;background:#FBFBF8;padding:32px;border-radius:16px;border-top:6px solid #1F7A8C\">\n<h3 style=\"font-size:32px;font-weight:700\">2 Always a pair</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">When one substance loses oxygen, another gains it, at the same time.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:10px;background:#FBFBF8;padding:32px;border-radius:16px;border-top:6px solid #1F7A8C\">\n<h3 style=\"font-size:32px;font-weight:700\">3 The agents</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">The reducing agent takes oxygen and is itself oxidized.</p>\n</div>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#E2F0F2;padding:32px;border-radius:16px\">\n<h3 style=\"font-size:32px;font-weight:700\">4 Reactivity series (most → least)</h3>\n<p style=\"font-size:28px;line-height:1.45;color:#1E2A3A\">K &gt; Na &gt; Ca &gt; Mg &gt; Al &gt; <b>C</b> &gt; Zn &gt; <b>Fe</b> &gt; Sn &gt; Pb &gt; <b>H</b> &gt; <b>Cu</b> &gt; Hg &gt; Ag &gt; Pt &gt; Au</p>\n<p style=\"font-size:28px;line-height:1.45;color:#3A4656\">Smelting: Fe₂O₃ + 3CO → 2Fe + 3CO₂ (carbon is more reactive than iron, so it takes the oxygen)</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L3 · Core Concept · 2–7 min</p>\n\n</section>", "note": "A more reactive element can replace a less reactive one in its compound. Link back to the hook: iron is more reactive than copper, so copper is pushed out of the solution."}, {"id": "myth", "html": "<section id=\"myth\" data-transition=\"fade\" style=\"background:#E8F1F2;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">True or False?</h2>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #1F7A8C\">1　“Oxidation and reduction are two separate reactions.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #1F7A8C\">2　“The more reactive a metal is, the more easily it is reduced.”</p>\n<p style=\"font-size:32px;line-height:1.45;background:#FBFBF8;padding:32px 40px;border-radius:16px;border-left:8px solid #1F7A8C\">3　“Rusting is only a color change, so it is a physical change.”</p>\n</div>\n<p style=\"font-size:28px;color:#5A6676\">Explain what’s wrong with each statement.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L3 · Misconceptions · 7–11 min</p>\n\n</section>", "note": "All three are false. 1: Oxidation and reduction always happen together. 2: A more reactive metal is more easily oxidized, and its oxide is harder to reduce. 3: Rust (iron oxide) is a new substance, so rusting is a chemical change and an oxidation."}, {"id": "practice", "html": "<section id=\"practice\" data-transition=\"fade\" style=\"background:#F7F5EF;color:#1E2A3A;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.1\">Pair Practice</h2>\n<div style=\"display:flex;gap:40px\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#17657A\">Q1</p>\n<p style=\"font-size:44px;font-weight:700\">2CuO + C → 2Cu + CO₂</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">Which substance is oxidized, which is reduced, and which is the reducing agent?</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFBF8;padding:48px;border-radius:20px;border:2px solid #E5E0D3\">\n<p style=\"font-size:28px;font-weight:700;color:#17657A\">Q2</p>\n<p style=\"font-size:44px;font-weight:700\">Cu + FeSO₄ → ?</p>\n<p style=\"font-size:32px;line-height:1.45;color:#3A4656\">Will a copper strip react with iron(II) sulfate solution? Why or why not?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#8A939E\">L3 · Practice · 11–14 min</p>\n\n</section>", "note": "Q1: C gains oxygen, so it is oxidized and is the reducing agent; CuO loses oxygen, so it is reduced and is the oxidizing agent. Q2: No reaction. Copper is less reactive than iron, so it cannot replace iron."}, {"id": "exit", "html": "<section id=\"exit\" data-transition=\"fade\" style=\"background:#17657A;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:40px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:2px;color:#CDE8EC\">EXIT TICKET · WORK ON YOUR OWN</p>\n<h2 style=\"font-size:72px;font-weight:700;line-height:1.2\">Use the reactivity series to explain why red copper appeared on the nail.</h2>\n<p style=\"font-size:32px;color:#CDE8EC\">One or two sentences.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#CDE8EC\">L3 · Exit Ticket · 14–15 min</p>\n\n</section>", "note": "Sample answer: Iron is more reactive than copper, so it replaces the copper in copper(II) sulfate, and red copper metal forms on the nail."}]}, "bio-osmosis-en": {"title": "Cells: Osmosis", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" style=\"background:#1F2A2E;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:28px;font-weight:700;color:#7CC7B8;letter-spacing:2px\">MIDDLE SCHOOL BIOLOGY MINI-LESSON 1/3</p>\n<div style=\"width:120px;height:8px;background:#7CC7B8\"></div>\n<h1 style=\"font-size:120px;font-weight:700;line-height:1.1\">Cells: Osmosis</h1>\n<p style=\"font-size:44px;font-weight:400;color:#7CC7B8\">How water moves in and out of cells</p>\n<p style=\"font-size:32px;color:#C9D3D0\">15 minutes · Grade 7 · Unit: Cells, the Basic Unit of Life</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#9AA8A4\">Objective: Students predict which way water moves across a cell membrane and explain it using concentration.</p>\n\n</section>", "note": "Prep: At least 40 minutes before class, soak 6 equal potato strips: 3 in plain water and 3 in 10% salt water. A 15-minute soak in class will not show a difference. Also bring cucumber slices, salt, rulers and paper towels. Timing: Hook 2 min, Vocabulary 2 min, Concept 4 min, Activity 5 min, Exit ticket 2 min."}, {"id": "hook", "html": "<section id=\"hook\" style=\"background:#E9EFEC;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">HOOK · 0–2 MIN</p>\n<div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<h1 style=\"font-size:96px;font-weight:700;line-height:1.15\">Why does salted cucumber get watery?</h1>\n</div>\n<div style=\"display:flex\">\n<p style=\"font-size:32px;font-weight:700;background:#1F2A2E;color:#F7F5EF;padding:24px 40px;border-radius:999px\">Guess first: where does the water come from?</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 2</p>\n\n</section>", "note": "At the start of class, sprinkle salt on cucumber slices and let them sit. Show the water on the plate at the end of this slide. Ask for a show of hands: did the water come from the salt, the air, or inside the cucumber? Hold the answer until the concept section."}, {"id": "vocab", "html": "<section id=\"vocab\" style=\"background:#F7F5EF;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">VOCABULARY · 2–4 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Four words to keep on the board</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px\">\n<div style=\"background:#FFFDF8;border:1px solid #E2DED3;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#1F6E62\">cell membrane</h3>\n<p style=\"font-size:28px;color:#4A5552\">The thin layer that controls what enters and leaves a cell</p>\n</div>\n<div style=\"background:#FFFDF8;border:1px solid #E2DED3;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#1F6E62\">diffusion</h3>\n<p style=\"font-size:28px;color:#4A5552\">Particles moving from high concentration to low concentration</p>\n</div>\n<div style=\"background:#FFFDF8;border:1px solid #E2DED3;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#1F6E62\">osmosis</h3>\n<p style=\"font-size:28px;color:#4A5552\">The diffusion of water across a cell membrane</p>\n</div>\n<div style=\"background:#FFFDF8;border:1px solid #E2DED3;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#1F6E62\">concentration</h3>\n<p style=\"font-size:28px;color:#4A5552\">How much of a substance (like salt) is in a given amount of water</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 3</p>\n\n</section>", "note": "Students copy the four words into their notes. Point out that osmosis is a special case of diffusion: same idea, but only water is moving."}, {"id": "concept", "html": "<section id=\"concept\" style=\"background:#F7F5EF;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">CORE CONCEPT · 4–8 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Water moves toward the saltier side</h2>\n</div>\n<div style=\"display:flex;gap:48px;align-items:start\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<svg aria-label=\"A cell in pure water: salt inside the cell, none outside; four arrows point inward and the cell swells\" width=\"480\" height=\"320\" viewBox=\"0 0 480 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" rx=\"16\" fill=\"#D6E8EF\"/>\n<circle cx=\"240\" cy=\"160\" r=\"100\" fill=\"#F7F5EF\" stroke=\"#1F6E62\" stroke-width=\"6\"/>\n<circle cx=\"205\" cy=\"125\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"275\" cy=\"135\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"225\" cy=\"195\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"270\" cy=\"195\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"240\" cy=\"160\" r=\"8\" fill=\"#1F2A2E\"/>\n<g stroke=\"#2E6FA8\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"#2E6FA8\">\n<line x1=\"30\" y1=\"160\" x2=\"118\" y2=\"160\"/><polygon points=\"135,160 113,146 113,174\" stroke=\"none\"/>\n<line x1=\"450\" y1=\"160\" x2=\"362\" y2=\"160\"/><polygon points=\"345,160 367,146 367,174\" stroke=\"none\"/>\n<line x1=\"240\" y1=\"10\" x2=\"240\" y2=\"34\"/><polygon points=\"240,50 226,28 254,28\" stroke=\"none\"/>\n<line x1=\"240\" y1=\"310\" x2=\"240\" y2=\"286\"/><polygon points=\"240,270 226,292 254,292\" stroke=\"none\"/>\n</g>\n</svg>\n<p style=\"font-size:32px;font-weight:700\">Pure water</p>\n<p style=\"font-size:28px;color:#4A5552\">Water moves in → cell swells</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<svg aria-label=\"A cell in salt water: more salt outside than inside; four arrows point outward and the cell shrinks\" width=\"480\" height=\"320\" viewBox=\"0 0 480 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"0\" y=\"0\" width=\"480\" height=\"320\" rx=\"16\" fill=\"#D6E8EF\"/>\n<circle cx=\"240\" cy=\"160\" r=\"70\" fill=\"#F7F5EF\" stroke=\"#1F6E62\" stroke-width=\"6\"/>\n<circle cx=\"240\" cy=\"160\" r=\"8\" fill=\"#1F2A2E\"/>\n<circle cx=\"60\" cy=\"60\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"110\" cy=\"270\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"400\" cy=\"60\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"420\" cy=\"265\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"80\" cy=\"225\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"395\" cy=\"215\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"130\" cy=\"90\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"345\" cy=\"95\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"350\" cy=\"275\" r=\"8\" fill=\"#1F2A2E\"/><circle cx=\"160\" cy=\"250\" r=\"8\" fill=\"#1F2A2E\"/>\n<g stroke=\"#2E6FA8\" stroke-width=\"8\" stroke-linecap=\"round\" fill=\"#2E6FA8\">\n<line x1=\"160\" y1=\"160\" x2=\"62\" y2=\"160\"/><polygon points=\"45,160 67,146 67,174\" stroke=\"none\"/>\n<line x1=\"320\" y1=\"160\" x2=\"418\" y2=\"160\"/><polygon points=\"435,160 413,146 413,174\" stroke=\"none\"/>\n<line x1=\"240\" y1=\"80\" x2=\"240\" y2=\"40\"/><polygon points=\"240,22 226,44 254,44\" stroke=\"none\"/>\n<line x1=\"240\" y1=\"240\" x2=\"240\" y2=\"280\"/><polygon points=\"240,298 226,276 254,276\" stroke=\"none\"/>\n</g>\n</svg>\n<p style=\"font-size:32px;font-weight:700\">Salt water</p>\n<p style=\"font-size:28px;color:#4A5552\">Water moves out → cell shrinks</p>\n</div>\n<div style=\"flex:1;background:#1F2A2E;color:#F7F5EF;padding:40px;border-radius:16px;display:flex;flex-direction:column;gap:20px\">\n<h3 style=\"font-size:44px;font-weight:700\">The rule</h3>\n<p style=\"font-size:32px;line-height:1.4\">Water moves toward the side with more salt.</p>\n<p style=\"font-size:24px;color:#BFD0CC\">Black dots = salt<br>Blue arrows = direction water moves</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 4</p>\n\n</section>", "note": "Draw one cell on the board with a few salt dots inside and outside. Key line: water moves toward the side with more salt. Back to the hook: the salt was on the outside of the cucumber, so water left the cucumber’s cells. The membrane lets water pass, but salt does not cross easily."}, {"id": "myth", "html": "<section id=\"myth\" style=\"background:#E9EFEC;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">COMMON MISCONCEPTION</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">The water moves, not the salt</h2>\n</div>\n<div style=\"display:flex;gap:32px\">\n<div style=\"flex:1;background:#F3E3DC;border:2px solid #B4532A;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#9A4320\">Misconception</p>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.3\">“The salt moves into the cell.”</h3>\n</div>\n<div style=\"flex:1;background:#F7F5EF;border:2px solid #1F6E62;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#1F6E62\">Correct</p>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.3\">The membrane lets water through. Salt does not cross easily.</h3>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 5</p>\n\n</section>", "note": "Students often read “more salt” as “the salt moves.” Close it with one line: the salt stays put; the water is what moves. If time is short, cover this orally during the concept section and skip the slide."}, {"id": "activity", "html": "<section id=\"activity\" style=\"background:#F7F5EF;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">ACTIVITY · 8–13 MIN · PAIRS</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Compare the two potato strips</h2>\n</div>\n<div style=\"display:flex;gap:56px;align-items:start\">\n<ol style=\"width:700px;font-size:32px;line-height:1.5\">\n<li>Take one strip from each cup.</li>\n<li>Measure each strip with a ruler.</li>\n<li>Gently bend each one. Which is firm? Which is soft?</li>\n<li>Decide: which strip gained water, and which lost water?</li>\n</ol>\n<table style=\"flex:1;font-size:28px;color:#1F2A2E;border:1px solid #CFCBC0\">\n<tr style=\"background:#E9EFEC\"><th style=\"width:28%\">Cup</th><th style=\"width:24%\">Length (cm)</th><th style=\"width:24%\">Firm or soft</th><th style=\"width:24%\">Gained or lost water</th></tr>\n<tr><td>Plain water</td><td>____</td><td>____</td><td>____</td></tr>\n<tr><td>Salt water</td><td>____</td><td>____</td><td>____</td></tr>\n</table>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 6</p>\n\n</section>", "note": "The strips must soak for at least 40 minutes beforehand (3 in plain water, 3 in 10% salt water). Expected results: the plain-water strip is firm and slightly longer (gained water); the salt-water strip is soft, bends easily and is slightly shorter (lost water). While circulating, ask: why is the salt-water strip soft?"}, {"id": "frames", "html": "<section id=\"frames\" style=\"background:#E9EFEC;color:#1F2A2E;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62;letter-spacing:2px\">SENTENCE FRAMES</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">State your conclusion in a full sentence</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<div style=\"background:#F7F5EF;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62\">Frame 1</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">The water moves ______ the cell because the concentration outside is ______.</p>\n</div>\n<div style=\"background:#F7F5EF;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#1F6E62\">Frame 2</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">The strip in ______ became ______ because it ______ water.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5E6866\">Cells: Osmosis · 7</p>\n\n</section>", "note": "Sample answers (salt-water strip): The water moves out of the cell because the concentration outside is higher. The strip in salt water became soft because it lost water. Have 2–3 pairs read their sentences aloud."}, {"id": "exit", "html": "<section id=\"exit\" style=\"background:#1F6E62;color:#F7F5EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#D8EEE8;letter-spacing:2px\">EXIT TICKET · 13–15 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Two questions, on your own</h2>\n</div>\n<div style=\"display:flex;gap:32px;align-items:stretch\">\n<div style=\"flex:1;background:#F7F5EF;color:#1F2A2E;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#1F6E62\">1</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">A red blood cell is placed in pure water. Which way does the water move? What happens to the cell?</p>\n</div>\n<div style=\"flex:1;background:#F7F5EF;color:#1F2A2E;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#1F6E62\">2</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">Why do grocery stores spray water on fresh vegetables?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#D8EEE8\">Cells: Osmosis · 8</p>\n\n</section>", "note": "Answers: 1. Water moves into the cell; the cell swells and may burst. 2. There is more water outside, so water moves into the cells and the vegetables stay crisp. Students who miss both: repeat the cucumber demo at the start of next class."}]}, "bio-genetics-en": {"title": "Genetics: Dominant & Recessive Traits", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" style=\"background:#2A2320;color:#FBF6EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:28px;font-weight:700;color:#F0A46B;letter-spacing:2px\">MIDDLE SCHOOL BIOLOGY MINI-LESSON 2/3</p>\n<div style=\"width:120px;height:8px;background:#F0A46B\"></div>\n<h1 style=\"font-size:120px;font-weight:700;line-height:1.1\">Genetics: Dominant &amp; Recessive Traits</h1>\n<p style=\"font-size:44px;font-weight:400;color:#F0A46B\">Predicting offspring with the Punnett square</p>\n<p style=\"font-size:32px;color:#D8CBBF\">15 minutes · Grade 7 · Unit: Heredity</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#B3A497\">Objective: Students complete an Aa × Aa Punnett square and find the 1:2:1 genotype and 3:1 phenotype ratios.</p>\n\n</section>", "note": "This is the highest-priority lesson of the three: heavily tested and full of misconceptions. Prep: 2 coins per pair, labeled with stickers (heads = A, tails = a); one tally sheet per pair; an empty 2×2 grid drawn on the board."}, {"id": "hook", "html": "<section id=\"hook\" style=\"background:#F4ECE3;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">HOOK · 0–2 MIN</p>\n<div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<h1 style=\"font-size:96px;font-weight:700;line-height:1.15\">Can two purple-flowered pea plants have a white-flowered offspring?</h1>\n</div>\n<div style=\"display:flex\">\n<p style=\"font-size:32px;font-weight:700;background:#2A2320;color:#FBF6EF;padding:24px 40px;border-radius:999px\">Vote: yes or no?</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 2</p>\n\n</section>", "note": "Show a photo or sketch of pea flowers if you have one. Take the vote and write the tally on the board without giving the answer. The answer is yes: if both purple parents are Aa, each offspring has a 1 in 4 chance of being white (aa). Avoid examples like eyelid folds or tongue rolling; they are controlled by several genes, not a simple dominant–recessive pair."}, {"id": "vocab", "html": "<section id=\"vocab\" style=\"background:#FBF6EF;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">VOCABULARY · 2–4 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Capital A = dominant, lowercase a = recessive</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px\">\n<div style=\"background:#FFFCF7;border:1px solid #E6DCCF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#A84B16\">gene</h3>\n<p style=\"font-size:28px;color:#5A4E45\">A unit of heredity that controls a trait</p>\n</div>\n<div style=\"background:#FFFCF7;border:1px solid #E6DCCF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#A84B16\">dominant (A)</h3>\n<p style=\"font-size:28px;color:#5A4E45\">Shows up when at least one copy is present</p>\n</div>\n<div style=\"background:#FFFCF7;border:1px solid #E6DCCF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#A84B16\">recessive (a)</h3>\n<p style=\"font-size:28px;color:#5A4E45\">Shows up only with two copies (aa)</p>\n</div>\n<div style=\"background:#FFFCF7;border:1px solid #E6DCCF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#A84B16\">genotype / phenotype</h3>\n<p style=\"font-size:28px;color:#5A4E45\">The letters, like Aa / The trait you can see, like purple</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 3</p>\n\n</section>", "note": "Stress the notation: a capital letter is dominant, the same letter in lowercase is recessive. Genotype is what you write; phenotype is what you see."}, {"id": "concept", "html": "<section id=\"concept\" style=\"background:#FBF6EF;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">CORE CONCEPT · 4–8 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">One letter from each parent</h2>\n</div>\n<div style=\"display:flex;gap:64px;align-items:start\">\n<div style=\"display:grid;grid-template-columns:200px 220px 220px;grid-template-rows:120px 170px 170px;gap:12px\">\n<div style=\"background:#FBF6EF;display:flex;flex-direction:column;align-items:center;justify-content:center\"><p style=\"font-size:28px;font-weight:700;color:#5A4E45;text-align:center\">Aa × Aa</p></div>\n<div style=\"background:#F4ECE3;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center\"><p style=\"font-size:24px;color:#5A4E45\">Mother</p><p style=\"font-size:44px;font-weight:700\">A</p></div>\n<div style=\"background:#F4ECE3;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center\"><p style=\"font-size:24px;color:#5A4E45\">Mother</p><p style=\"font-size:44px;font-weight:700\">a</p></div>\n<div style=\"background:#F4ECE3;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center\"><p style=\"font-size:24px;color:#5A4E45\">Father</p><p style=\"font-size:44px;font-weight:700\">A</p></div>\n<div style=\"background:#FFFCF7;border:2px solid #D9CBBB;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px\"><p style=\"font-size:56px;font-weight:700\">AA</p><p style=\"font-size:24px;color:#5A4E45\">purple</p></div>\n<div style=\"background:#FFFCF7;border:2px solid #D9CBBB;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px\"><p style=\"font-size:56px;font-weight:700\">Aa</p><p style=\"font-size:24px;color:#5A4E45\">purple</p></div>\n<div style=\"background:#F4ECE3;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center\"><p style=\"font-size:24px;color:#5A4E45\">Father</p><p style=\"font-size:44px;font-weight:700\">a</p></div>\n<div style=\"background:#FFFCF7;border:2px solid #D9CBBB;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px\"><p style=\"font-size:56px;font-weight:700\">Aa</p><p style=\"font-size:24px;color:#5A4E45\">purple</p></div>\n<div style=\"background:#A84B16;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px\"><p style=\"font-size:56px;font-weight:700;color:#FBF6EF\">aa</p><p style=\"font-size:24px;font-weight:700;color:#FBF6EF\">white</p></div>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px\">\n<div style=\"background:#2A2320;color:#FBF6EF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#F0A46B\">Genotype ratio</p>\n<p style=\"font-size:44px;font-weight:700\">AA : Aa : aa = 1 : 2 : 1</p>\n</div>\n<div style=\"background:#2A2320;color:#FBF6EF;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#F0A46B\">Phenotype ratio</p>\n<p style=\"font-size:44px;font-weight:700\">purple : white = 3 : 1</p>\n</div>\n<p style=\"font-size:32px;line-height:1.4\">Chance of white = 1 in 4 = 25%</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 4</p>\n\n</section>", "note": "Fill in the 2×2 grid on the board with the class: the mother’s two letters (A, a) across the top, the father’s (A, a) down the side, and combine them in each box. Back to the hook: the answer is yes. If both purple parents are Aa, each offspring has a 1 in 4 chance of being white (aa)."}, {"id": "myth", "html": "<section id=\"myth\" style=\"background:#F4ECE3;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">COMMON MISCONCEPTION</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Every offspring is a new chance</h2>\n</div>\n<div style=\"display:flex;gap:32px\">\n<div style=\"flex:1;background:#EFDCCD;border:2px solid #A84B16;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#8C3D10\">Misconception</p>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.3\">“After 3 purple plants, the 4th one must be white.”</h3>\n</div>\n<div style=\"flex:1;background:#FBF6EF;border:2px solid #2A2320;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#2A2320\">Correct</p>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.3\">Each offspring has its own 1 in 4 chance of being white.</h3>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 5</p>\n\n</section>", "note": "Analogy: after flipping heads three times in a row, the fourth flip is still 50/50. A 1:2:1 ratio is what you approach over many offspring, not a guarantee for every group of four. This leads straight into the coin activity."}, {"id": "activity", "html": "<section id=\"activity\" style=\"background:#FBF6EF;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">ACTIVITY · 8–13 MIN · PAIRS</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Flip coins to model gametes</h2>\n</div>\n<div style=\"display:flex;gap:56px;align-items:start\">\n<ol style=\"width:700px;font-size:32px;line-height:1.5\">\n<li>One partner is the father, one is the mother. Heads = A, tails = a.</li>\n<li>Flip at the same time and record the pair.</li>\n<li>Repeat 20 times.</li>\n<li>Add up the class totals and compare with 1:2:1.</li>\n</ol>\n<table style=\"flex:1;font-size:28px;color:#2A2320;border:1px solid #D9CBBB\">\n<tr style=\"background:#F4ECE3\"><th style=\"width:22%\">Pair</th><th style=\"width:26%\">Our count</th><th style=\"width:26%\">Class total</th><th style=\"width:26%\">Expected</th></tr>\n<tr><td>AA</td><td>____</td><td>____</td><td>1/4</td></tr>\n<tr><td>Aa</td><td>____</td><td>____</td><td>2/4</td></tr>\n<tr><td>aa</td><td>____</td><td>____</td><td>1/4</td></tr>\n<tr style=\"background:#F4ECE3\"><td>Total</td><td>20</td><td>____</td><td>1</td></tr>\n</table>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 6</p>\n\n</section>", "note": "Remind students that A + a and a + A both count as Aa. In the last minute, collect each pair’s counts on the board and total them. One pair’s 20 flips often misses 1:2:1; the class total of several hundred flips comes closer. This sets up exit ticket question 2."}, {"id": "frames", "html": "<section id=\"frames\" style=\"background:#F4ECE3;color:#2A2320;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16;letter-spacing:2px\">SENTENCE FRAMES</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">State your conclusion in a full sentence</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<div style=\"background:#FBF6EF;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16\">Frame 1</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">The chance of a recessive offspring is ______ because only ______ shows the recessive trait.</p>\n</div>\n<div style=\"background:#FBF6EF;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#A84B16\">Frame 2</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">Our class results were ______ to 1:2:1 because ______.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#6B5F55\">Genetics: Dominant &amp; Recessive · 7</p>\n\n</section>", "note": "Sample answers: The chance of a recessive offspring is 1/4 because only aa shows the recessive trait. Our class results were close to 1:2:1 because we flipped many times."}, {"id": "exit", "html": "<section id=\"exit\" style=\"background:#A84B16;color:#FBF6EF;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#FBE9DA;letter-spacing:2px\">EXIT TICKET · 13–15 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Two questions, on your own</h2>\n</div>\n<div style=\"display:flex;gap:32px;align-items:stretch\">\n<div style=\"flex:1;background:#FBF6EF;color:#2A2320;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#A84B16\">1</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">The father is Aa and the mother is aa. What is the chance of a recessive offspring? Draw the Punnett square.</p>\n</div>\n<div style=\"flex:1;background:#FBF6EF;color:#2A2320;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#A84B16\">2</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">Why didn’t 20 flips give exactly 1:2:1, while the class total came closer?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#FBE9DA\">Genetics: Dominant &amp; Recessive · 8</p>\n\n</section>", "note": "Answers: 1. 1/2 (Aa : aa = 2 : 2). 2. Probability only gets close to the expected ratio with a large number of trials. Students who answer 1/4 on question 1 probably reused the Aa × Aa result; next time, have them draw the square before calculating."}]}, "bio-ecology-en": {"title": "Ecology: Food Webs & Energy Pyramids", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" style=\"background:#1F2A1C;color:#F6F7F0;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<p style=\"font-size:28px;font-weight:700;color:#A8D08D;letter-spacing:2px\">MIDDLE SCHOOL BIOLOGY MINI-LESSON 3/3</p>\n<div style=\"width:120px;height:8px;background:#A8D08D\"></div>\n<h1 style=\"font-size:120px;font-weight:700;line-height:1.1\">Ecology: Food Webs &amp; Energy Pyramids</h1>\n<p style=\"font-size:44px;font-weight:400;color:#A8D08D\">Who eats whom, and where the energy goes</p>\n<p style=\"font-size:32px;color:#CBD4C3\">15 minutes · Grade 7 · Unit: Living Things and the Environment</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#A3AE9B\">Objective: Students draw a food web with at least 5 organisms and use the 10% rule to calculate energy transfer.</p>\n\n</section>", "note": "Prep: 8 role cards (Sun, Grass, Rabbit, Deer, Mouse, Snake, Hawk, Wolf); one ball of yarn; a map or sketch of Yellowstone National Park."}, {"id": "hook", "html": "<section id=\"hook\" style=\"background:#EAF0E2;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">HOOK · 0–2 MIN</p>\n<div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;gap:32px\">\n<h1 style=\"font-size:88px;font-weight:700;line-height:1.2\">After wolves were removed from Yellowstone, why did the riverside trees disappear?</h1>\n</div>\n<div style=\"display:flex\">\n<p style=\"font-size:32px;font-weight:700;background:#1F2A1C;color:#F6F7F0;padding:24px 40px;border-radius:999px\">Tell a partner one guess.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 2</p>\n\n</section>", "note": "Background: wolves were hunted out of Yellowstone by the 1920s. Without wolves, the elk population grew and overgrazed the willows and aspens along the rivers. Wolves were reintroduced in 1995. Let students guess; reveal the chain reaction during the yarn activity."}, {"id": "vocab", "html": "<section id=\"vocab\" style=\"background:#F6F7F0;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">VOCABULARY · 2–4 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Give one example of each</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px\">\n<div style=\"background:#FCFDF8;border:1px solid #DCE2D2;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#3D6B22\">producer</h3>\n<p style=\"font-size:28px;color:#4E5A47\">Makes its own food, like grass or trees</p>\n</div>\n<div style=\"background:#FCFDF8;border:1px solid #DCE2D2;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#3D6B22\">consumer</h3>\n<p style=\"font-size:28px;color:#4E5A47\">Gets energy by eating other living things, like rabbits or wolves</p>\n</div>\n<div style=\"background:#FCFDF8;border:1px solid #DCE2D2;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#3D6B22\">decomposer</h3>\n<p style=\"font-size:28px;color:#4E5A47\">Breaks down dead organisms, like bacteria and fungi</p>\n</div>\n<div style=\"background:#FCFDF8;border:1px solid #DCE2D2;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:12px\">\n<h3 style=\"font-size:44px;font-weight:700;color:#3D6B22\">food web</h3>\n<p style=\"font-size:28px;color:#4E5A47\">Many food chains linked together</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 3</p>\n\n</section>", "note": "Ask students to give one example of their own for each word. Decomposers are often forgotten; remind students they break down every organism in the web once it dies."}, {"id": "concept", "html": "<section id=\"concept\" style=\"background:#F6F7F0;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">CORE CONCEPT · 4–8 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Only about 10% moves up each level</h2>\n</div>\n<div style=\"display:flex;gap:56px;align-items:center\">\n<div style=\"width:1040px;display:flex;flex-direction:column;align-items:center;gap:8px\">\n<div style=\"width:360px;background:#3D6B22;border-radius:12px;padding:24px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:32px;font-weight:700;color:#F6F7F0\">Wolf · 100 kJ</p></div>\n<p style=\"font-size:24px;color:#4E5A47\">↑ about 10% passes up</p>\n<div style=\"width:700px;background:#86A866;border-radius:12px;padding:24px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:32px;font-weight:700;color:#1F2A1C\">Rabbit · 1,000 kJ</p></div>\n<p style=\"font-size:24px;color:#4E5A47\">↑ about 10% passes up</p>\n<div style=\"width:1040px;background:#C9DBB5;border-radius:12px;padding:24px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:32px;font-weight:700;color:#1F2A1C\">Grass · 10,000 kJ</p></div>\n</div>\n<div style=\"flex:1;background:#1F2A1C;color:#F6F7F0;border-radius:16px;padding:40px;display:flex;flex-direction:column;gap:20px\">\n<h3 style=\"font-size:44px;font-weight:700\">Try it</h3>\n<p style=\"font-size:32px;line-height:1.4\">If something eats the wolf, how much energy reaches level 4?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 4</p>\n\n</section>", "note": "Answer: 10 kJ. At each level about 90% is used for breathing and movement and lost as heat, or stays in parts that are not eaten. That is why top predators are the fewest. 10% is an approximation; it is the standard figure in textbooks and tests."}, {"id": "myth", "html": "<section id=\"myth\" style=\"background:#EAF0E2;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">COMMON MISCONCEPTION</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Arrows show where the energy goes</h2>\n</div>\n<div style=\"display:flex;gap:32px\">\n<div style=\"flex:1;background:#F1E2D6;border:2px solid #A0522D;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#8A4424\">Misconception</p>\n<h3 style=\"font-size:56px;font-weight:700\">Wolf → Rabbit → Grass</h3>\n<p style=\"font-size:32px;color:#4E5A47;line-height:1.4\">The arrow points to what gets eaten.</p>\n</div>\n<div style=\"flex:1;background:#F6F7F0;border:2px solid #3D6B22;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:28px;font-weight:700;color:#3D6B22\">Correct</p>\n<h3 style=\"font-size:56px;font-weight:700\">Grass → Rabbit → Wolf</h3>\n<p style=\"font-size:32px;color:#4E5A47;line-height:1.4\">The arrow follows the energy: from the eaten to the eater.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 5</p>\n\n</section>", "note": "Tip: read each arrow as “is eaten by” or “energy flows to.” Grass is eaten by the rabbit; the rabbit is eaten by the wolf. When students draw their webs, have them check that every arrow points up from the producers."}, {"id": "activity", "html": "<section id=\"activity\" style=\"background:#F6F7F0;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">ACTIVITY · 8–13 MIN · CIRCLE OF 8</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Build a food web with yarn</h2>\n</div>\n<div style=\"display:flex;gap:56px;align-items:start\">\n<ol style=\"width:780px;font-size:32px;line-height:1.5\">\n<li>Eight students each take a role card and stand in a circle.</li>\n<li>Pass the yarn from each organism to whatever eats it.</li>\n<li>The teacher says “The wolf is gone.” The wolf lets go.</li>\n<li>Who feels the yarn change? Describe the chain reaction.</li>\n</ol>\n<div style=\"flex:1;display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:16px\">\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Sun</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Grass</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Rabbit</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Deer</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Mouse</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Snake</p></div>\n<div style=\"background:#EAF0E2;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700\">Hawk</p></div>\n<div style=\"background:#3D6B22;border-radius:12px;padding:24px 8px;display:flex;flex-direction:column;align-items:center\"><p style=\"font-size:28px;font-weight:700;color:#F6F7F0\">Wolf</p></div>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 6</p>\n\n</section>", "note": "Suggested links: Sun → Grass; Grass → Rabbit, Deer, Mouse; Rabbit → Snake, Hawk, Wolf; Mouse → Snake, Hawk; Deer → Wolf; Snake → Hawk. When the wolf lets go, the Deer student feels the yarn go slack. Guide students to say: no wolves → more deer → grass and trees get eaten. Students not in the circle draw the same web at their desks."}, {"id": "frames", "html": "<section id=\"frames\" style=\"background:#EAF0E2;color:#1F2A1C;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22;letter-spacing:2px\">SENTENCE FRAMES</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">State your conclusion in a full sentence</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<div style=\"background:#F6F7F0;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22\">Frame 1</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">If the ______ disappears, the ______ will increase because ______.</p>\n</div>\n<div style=\"background:#F6F7F0;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#3D6B22\">Frame 2</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">Only about ______% of the energy in ______ passes to ______.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#5F6B58\">Ecology: Food Webs &amp; Energy Pyramids · 7</p>\n\n</section>", "note": "Sample answers: If the wolf disappears, the deer will increase because nothing eats them. Only about 10% of the energy in grass passes to rabbits. Extension: ask students to add a sentence starting “So the trees will…”"}, {"id": "exit", "html": "<section id=\"exit\" style=\"background:#3D6B22;color:#F6F7F0;font-family:'Nunito', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-size:24px;font-weight:700;color:#E3ECD9;letter-spacing:2px\">EXIT TICKET · 13–15 MIN</p>\n<h2 style=\"font-size:64px;font-weight:700;line-height:1.15\">Two questions, on your own</h2>\n</div>\n<div style=\"display:flex;gap:32px;align-items:stretch\">\n<div style=\"flex:1;background:#F6F7F0;color:#1F2A1C;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#3D6B22\">1</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">Grass stores 50,000 kJ of energy. Using the 10% rule, how much energy reaches a hawk that eats rabbits (level 3)?</p>\n</div>\n<div style=\"flex:1;background:#F6F7F0;color:#1F2A1C;border-radius:16px;padding:48px;display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-size:64px;font-weight:700;color:#3D6B22\">2</p>\n<p style=\"font-size:32px;font-weight:700;line-height:1.4\">Why do food chains rarely have more than 4 or 5 levels?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:1664px;font-size:24px;color:#E3ECD9\">Ecology: Food Webs &amp; Energy Pyramids · 8</p>\n\n</section>", "note": "Answers: 1. 500 kJ (50,000 → 5,000 → 500). 2. About 90% of the energy is lost at each level, so the top levels do not have enough energy to support a population. Students who answer 5,000 skipped a level; have them write out all three levels first."}]}};
window.DECK_FONTS = ["https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@500;700&display=swap", "https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700&display=swap", "https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&display=swap", "https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;700;800;900&display=swap", "https://fonts.googleapis.com/css2?family=Nunito:wght@400..800&display=swap", "https://fonts.googleapis.com/css2?family=Nunito:wght@400;700&display=swap"];
